// JS in-memory router. Renders screens sequentially from the active funnel
// config (src/config/funnels.js — pick with ?funnel=, default reunion).
// Each screen module exports a function (screen, advance) → DOM node.
//
// Layout contract (mobile-first, viewport-locked):
// - #app is h-dvh; screens are h-full flex columns and NEVER scroll the page.
// - Primary CTAs live in a shrink-0 footer or a `.cta-dock` overlay — they are
//   always visible without scrolling (funnel rule: never hide the CTA).
// - Long content goes in `.screen-scroll` which scrolls UNDER the cta-dock.
//
// Motion (per gsap-timeline + gsap-performance skills): one enter timeline per
// screen with defaults, child stagger via transforms/autoAlpha only; groups
// marked [data-stagger] get per-item stagger; [data-media] gets a slow settle
// scale; [data-cta-pulse] gets a subtle repeating attention pulse.
//
// Tracking is fully config-driven: events derive from screen type + index
// (src/tracking.js mirrors the funnel-tracking rule store) — screens can be
// added/removed in JSON without touching this file.

import gsap from 'gsap';
import { resolveFunnel, urlModes } from './config/funnels.js';
import { engagementQuestion } from './screens/engagement-question.js';
import { engagementInsert } from './screens/engagement-insert.js';
import { engagementUpload } from './screens/engagement-upload.js';
import { showcase } from './screens/showcase.js';
import { loading } from './screens/loading.js';
import { trust } from './screens/trust.js';
import { testimonialCarousel } from './screens/testimonial-carousel.js';
import { wheel } from './screens/wheel.js';
import { paywall } from './screens/paywall.js';
import { successfull } from './screens/successfull.js';
import { raw } from './screens/raw.js';
import {
  initTracking,
  track,
  trackScreenView,
  trackScreenContinue,
  trackFunnelComplete,
} from './tracking.js';
import { getState, setIndex } from './state.js';
import { handleCheckoutReturn } from './payments/index.js';

const RENDERERS = {
  'engagement-question': engagementQuestion,
  'engagement-insert': engagementInsert,
  'engagement-upload': engagementUpload,
  'showcase': showcase,
  'loading': loading,
  'trust': trust,
  'testimonial-carousel': testimonialCarousel,
  'wheel': wheel,
  'paywall': paywall,
  'successfull': successfull,
  'raw': raw,
};

const THEME_COLORS = { 'reunion-dark': '#0a0203', light: '#f8fafc' };

let funnel = null;
let screens = [];
const root = document.getElementById('app');

export async function start() {
  funnel = await resolveFunnel();
  screens = funnel.screens;
  const theme = funnel.theme || 'light';
  document.body.dataset.theme = theme;
  // Webname + favicon (operator 2026-07-03): branding theo PRODUCT
  // (products.json siteName/favicon), funnel override bằng webName/favicon.
  // Tab hiển thị tên sạch ("Artimind") — không lộ tên biến thể nội bộ.
  document.title = funnel.webName || funnel.siteName || 'Artimind';
  const fav = funnel.favicon;
  if (fav) {
    const link = document.querySelector('link[rel="icon"]') || document.head.appendChild(Object.assign(document.createElement('link'), { rel: 'icon' }));
    link.href = fav;
  }
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.content = THEME_COLORS[theme] || THEME_COLORS.light;
  if (!screens.length) {
    root.innerHTML = '<div class="m-auto t-muted">Empty funnel — edit src/config/funnels/*.json</div>';
    return;
  }
  initTracking(funnel, getState());
  // Returning from an embedded/hosted checkout (?status=complete) → jump to
  // the funnel's `successfull` screen (fallback: built-in success view)
  // instead of restarting from screen 0.
  const successIdx = screens.findIndex((s) => s.type === 'successfull');
  if (handleCheckoutReturn(funnel, (info) => (successIdx >= 0 ? render(successIdx) : finishSuccess(info)))) return;
  // hậu tố /purchase → đi thẳng màn thanh toán (test/demo/deep-link)
  if (urlModes().purchase) {
    const payIdx = screens.findIndex((s) => s.type === 'paywall');
    if (payIdx >= 0) return render(payIdx);
  }
  render(0);
}

// Runtime handle for the on-page editor (src/editor.js) and payments layer.
export function getRuntime() {
  return {
    funnel,
    screens,
    render,
    finishSuccess,
    currentIndex: () => getState().currentIndex,
    applyScreenPatch(screenId, patch) {
      const i = screens.findIndex((s) => s.id === screenId);
      if (i < 0) return false;
      screens[i] = { ...screens[i], ...patch };
      if (getState().currentIndex === i) render(i);
      return true;
    },
  };
}

function render(i) {
  const state = getState();
  if (i >= screens.length) return finish();
  setIndex(i);
  const screen = { ...screens[i], index: i, total: screens.length, funnel };
  const renderer = RENDERERS[screen.type];
  if (!renderer) {
    console.warn(`No renderer for screen type "${screen.type}"`);
    return advance({ skipped: true });
  }
  trackScreenView(screen);
  const node = renderer(screen, advance);
  root.replaceChildren(node);
  enterTransition(node);
}

function enterTransition(node) {
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  const tl = gsap.timeline({ defaults: { ease: 'power2.out', duration: 0.5 } });
  tl.from(node, { autoAlpha: 0, duration: 0.3 });

  // Wheel screen choreographs itself (CSS idle/spin animations own the
  // transforms) — fade only, no child transforms that would fight them.
  if (!node.classList.contains('wheel-screen')) {
    const kids = [...node.children].filter(
      (el) => !el.classList.contains('cta-dock') && !el.hasAttribute('data-stagger'),
    );
    if (kids.length) {
      tl.from(kids, { y: 22, autoAlpha: 0, stagger: 0.07, clearProps: 'all' }, '<0.05');
    }
    node.querySelectorAll('[data-stagger]').forEach((group) => {
      if (group.children.length) {
        tl.from(
          [...group.children],
          { y: 16, autoAlpha: 0, stagger: 0.06, clearProps: 'all' },
          '<0.12',
        );
      }
    });
    const dock = node.querySelector('.cta-dock');
    if (dock) tl.from(dock, { y: 28, autoAlpha: 0, clearProps: 'all' }, '<0.1');
  }

  // Media settle — slow scale-down, transform-only (gsap-performance).
  const media = node.querySelector('[data-media]');
  if (media) tl.from(media, { scale: 1.06, duration: 1.1, ease: 'power3.out', clearProps: 'scale' }, 0.1);

  // CTA attention pulse — subtle infinite yoyo, starts after entrance.
  const pulse = node.querySelector('[data-cta-pulse]');
  if (pulse) {
    gsap.to(pulse, { scale: 1.025, duration: 0.85, repeat: -1, yoyo: true, ease: 'sine.inOut', delay: 1.2 });
  }
}

function advance(payload) {
  const state = getState();
  const screen = { ...screens[state.currentIndex], index: state.currentIndex };
  trackScreenContinue(screen, payload || {});
  // Semantic extras stay type-driven (no per-screen wiring): a wheel advance
  // carries the spin result → funnel_wheel_spin.
  if (screen.type === 'wheel' && payload && payload.discount !== undefined) {
    track('funnel_wheel_spin', { screen_id: screen.id, screen_index: screen.index, discount_pct: payload.discount });
  }
  render(state.currentIndex + 1);
}

function finish() {
  const state = getState();
  trackFunnelComplete(state);
  // Hết màn: đứng lại ở màn successfull nếu có (màn cuối theo funnelfox) —
  // KHÔNG BAO GIỜ lộ debug ra user thật (bug live 2026-07-03: user thấy
  // "Funnel complete + Session ID"). Debug chỉ ở dev build.
  const successIdx = screens.findIndex((s) => s.type === 'successfull');
  if (successIdx >= 0) return render(successIdx);
  if (import.meta.env.PROD) return finishSuccess({});
  root.innerHTML = `
    <section class="m-auto flex flex-col items-center gap-4 py-12 text-center">
      <div class="text-5xl">🎉</div>
      <h2 class="t-title text-2xl font-bold">Funnel complete</h2>
      <p class="t-muted">Session ID: <code class="card-surface px-2 py-1 text-sm">${state.sessionId.slice(0, 8)}</code></p>
      ${state.discountPct ? `<p class="t-muted">Discount carried to checkout: <strong style="color:var(--c-gold)">${state.discountPct}% OFF</strong></p>` : ''}
      <details class="w-full text-left">
        <summary class="t-faint cursor-pointer text-sm">Debug — captured answers (dev only)</summary>
        <pre class="card-surface mt-2 overflow-x-auto p-3 text-xs">${JSON.stringify(state.answers, null, 2)}</pre>
      </details>
    </section>
  `;
}

// Post-purchase success screen (embedded checkout return or in-page success).
function finishSuccess(info = {}) {
  const state = getState();
  root.innerHTML = `
    <section class="m-auto flex flex-col items-center gap-4 py-12 text-center">
      <div class="text-5xl">👑</div>
      <h2 class="t-title text-2xl font-bold">Payment received — welcome!</h2>
      <p class="t-muted">Your plan is active. Check your email for the receipt${info.provider ? ` (via ${info.provider})` : ''}.</p>
      <p class="t-faint text-sm">Session: <code class="card-surface px-2 py-1">${state.sessionId.slice(0, 8)}</code></p>
    </section>
  `;
}
