// Raw screen — dùng khi IMPORT template (Templates › Import).
//   screen.url  → nhúng LIVE trang qua <iframe> (trang JS/SPA như FunnelFox
//                 render không ra HTML tĩnh → phải embed mới hiển thị đúng).
//   screen.html → render markup tĩnh (page thường / file HTML upload), đã
//                 strip script/iframe/link/on* ở server.
// UA mở builder để tách nhỏ thành các màn chuẩn sau.
export function raw(screen, advance) {
  const root = document.createElement('section');
  root.className = 'relative flex h-full min-h-0 flex-1 flex-col';
  if (screen.url) {
    // Import = funnel LIVE đầy đủ → chiếm TRỌN viewport (thoát khung max-w-md +
    // padding của #app; nếu để trong flex/h-full sẽ bị bóp lại 1 ô nhỏ).
    root.style.cssText = 'position:fixed;inset:0;z-index:1;background:#fff';
    root.innerHTML = `<iframe src="${escAttr(screen.url)}" title="imported funnel"
        style="border:0;width:100vw;height:100dvh;display:block;background:#fff"
        loading="lazy" referrerpolicy="no-referrer"></iframe>`;
    return root;
  }
  root.innerHTML = `
    <div class="screen-scroll" style="padding-bottom:96px">${screen.html || '<p class="t-muted" style="padding:24px;color:#8a8f9c">Màn import trống — mở lại Import.</p>'}</div>
    <div class="cta-dock"><button type="button" class="btn-primary" data-cta data-cta-pulse>${escapeHtml(screen.cta || 'Continue')}</button></div>`;
  const b = root.querySelector('[data-cta]');
  if (b) b.onclick = () => advance({});
  return root;
}
function escapeHtml(s) { return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]); }
function escAttr(s) { return String(s).replace(/"/g, '&quot;'); }
