// PayPal adapter — JS SDK subscription buttons.
//
// Config (funnel.payment.paypal): { env: 'sandbox'|'live', clientId,
//   planIds: { week, month, year } }  — plan ids from
//   web2app/tools/paypal-setup/planids{,.live}.json (P-… billing plans,
//   $9.99/19.99/49.99, created 2026-06-29 for the Funnelfox trial).
//
// custom_id = "s=<session_id>" — same join-key convention as the Funnelfox
// PayPal trial (BQ recon joins custom_id ⇔ session id), so purchases land in
// hiepnv.paypal_funnel_purchases without new plumbing.

import { openModal, closeModal, modalBody } from './modal.js';

let sdkPromise = null;
function loadSdk(cfg) {
  if (window.paypal) return Promise.resolve();
  if (sdkPromise) return sdkPromise;
  const params = new URLSearchParams({
    'client-id': cfg.clientId,
    vault: 'true',
    intent: 'subscription',
  });
  sdkPromise = new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = `https://www.paypal.com/sdk/js?${params}`;
    s.onload = resolve;
    s.onerror = () => reject(new Error('PayPal SDK failed to load'));
    document.head.appendChild(s);
  });
  return sdkPromise;
}

export async function checkout(cfg, plan, { done, fail, sessionId }) {
  const planId = cfg?.planIds?.[plan?.id];
  if (!cfg?.clientId) { fail?.(new Error('PayPal not configured')); return { ok: false }; }
  if (!planId) { fail?.(new Error(`No PayPal plan id for "${plan?.id}"`)); return { ok: false }; }
  openModal(`Subscribe with PayPal — ${plan?.label || 'plan'}`);
  const mount = modalBody();
  try {
    await loadSdk(cfg);
    mount.innerHTML = '<div data-paypal-buttons style="min-height:120px"></div>';
    return await new Promise((resolve) => {
      window.paypal
        .Buttons({
          style: { layout: 'vertical', shape: 'rect', label: 'subscribe' },
          createSubscription: (data, actions) =>
            actions.subscription.create({
              plan_id: planId,
              custom_id: `s=${sessionId || ''}`,
            }),
          onApprove: (data) => {
            closeModal();
            done?.({ subscription_id: data.subscriptionID });
            resolve({ ok: true, provider: 'paypal', subscriptionId: data.subscriptionID });
          },
          onError: (err) => {
            fail?.(err);
            resolve({ ok: false, error: err });
          },
          onCancel: () => {
            resolve({ ok: false, cancelled: true });
          },
        })
        .render(mount.querySelector('[data-paypal-buttons]'));
    });
  } catch (e) {
    if (mount) mount.innerHTML = `<p style="color:#c0392b;margin:0;text-align:center;padding:24px 0">${String(e?.message || 'PayPal failed.')}</p>`;
    fail?.(e);
    return { ok: false, error: e };
  }
}
