// Shared checkout modal — theme-aware scrim + card. Providers mount their
// UI into modalBody(). One modal at a time.

let activeCleanup = null;

export function openModal(title, { onClose } = {}) {
  closeModal();
  const scrim = document.createElement('div');
  scrim.id = 'checkout-modal';
  scrim.style.cssText =
    'position:fixed;inset:0;z-index:60;display:flex;align-items:flex-end;justify-content:center;' +
    'background:rgba(0,0,0,0.6);backdrop-filter:blur(2px)';
  scrim.innerHTML = `
    <div data-modal-card style="width:100%;max-width:430px;max-height:88dvh;overflow-y:auto;
         border-radius:20px 20px 0 0;background:#fff;color:#1a1a1a;padding:16px 16px 24px;position:relative">
      <button type="button" data-modal-close aria-label="Close"
        style="position:absolute;top:10px;right:12px;font-size:20px;line-height:1;border:none;background:none;cursor:pointer;color:#888">✕</button>
      <h3 style="font-weight:700;font-size:16px;margin:2px 24px 12px 2px">${escapeHtml(title || 'Complete your purchase')}</h3>
      <div data-modal-body><div style="text-align:center;color:#888;padding:32px 0">Loading secure checkout…</div></div>
    </div>`;
  scrim.querySelector('[data-modal-close]').onclick = () => {
    closeModal();
    onClose?.();
  };
  scrim.addEventListener('click', (e) => {
    if (e.target === scrim) {
      closeModal();
      onClose?.();
    }
  });
  document.body.appendChild(scrim);
  return scrim;
}

export function modalBody() {
  return document.querySelector('#checkout-modal [data-modal-body]');
}

export function onModalCleanup(fn) {
  activeCleanup = fn;
}

export function closeModal() {
  try { activeCleanup?.(); } catch { /* noop */ }
  activeCleanup = null;
  document.getElementById('checkout-modal')?.remove();
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
}
