// On-page content editor — the MKT workflow (operator 2026-07-03):
//   Huy (MKT manager) creates a TEMPLATE (concept) →
//   each MKTer CLONES it and edits content ON THE PAGE →
//   Save writes src/config/funnels/<id>.json via the vite dev API.
//
// Open any funnel with ?editor=1:
//   • preview renders in an IFRAME framed as an iPhone 13 (390×844), CENTERED
//     in the space left of the drawer (operator 2026-07-03) — dvh/safe-area
//     inside the iframe match a real phone viewport, so the CTA-in-viewport
//     rule is previewed faithfully. Auto-scales down on short monitors.
//   • screen list (index · id · type) — click to preview that screen
//   • editable content fields for the selected screen (text/URLs/options)
//   • Apply = live re-render · Save = persist funnel JSON (clone keeps ONLY
//     the fields you changed, as overrides — template updates flow through)
//   • Clone as… = new funnel id + style + owner (MKTer name)
//   • Export = copy a ?rc= preview link (same override JSON, no save needed)
//
// Editor/preview sessions are muted in tracking (console only) so they never
// pollute funnel data. Save/Clone talk to /__funnel/save which only exists on
// the vite dev server; on a production build they report the limitation.

import { TEMPLATES, FUNNELS } from './config/funnels.js';

// Device presets — default iPhone 13; switchable (operator 2026-07-03).
const DEVICES = [
  { id: 'iphone-se', label: 'iPhone SE', w: 375, h: 667 },
  { id: 'iphone-11', label: 'iPhone 11', w: 414, h: 896 },
  { id: 'iphone-12', label: 'iPhone 12', w: 390, h: 844 },
  { id: 'iphone-13', label: 'iPhone 13', w: 390, h: 844 },
  { id: 'iphone-14-pro-max', label: 'iPhone 14 Pro Max', w: 430, h: 932 },
  { id: 'pixel-7', label: 'Pixel 7', w: 412, h: 915 },
];
const DEVICE_KEY = 'funnel-editor-device';
// Funnel chạy trên WEB — mô phỏng browser chrome ở đỉnh màn (operator
// 2026-07-03): 1 khoảng "(Browser tab here)" chiếm chỗ đúng như tab thật,
// nên viewport funnel = device height − browser bar.
const BROWSER_BAR_H = 54;
const DRAWER_W = 340;

// Content fields MKTers may edit, per screen (strings unless noted).
// ALWAYS_FIELDS hiển thị ở MỌI màn kể cả khi config chưa có (operator
// 2026-07-03: eyebrowImage setup được tại tất cả các màn).
const ALWAYS_FIELDS = ['title', 'cta', 'eyebrowImage'];
const EDITABLE = [
  'title', 'subtitle', 'body', 'eyebrow', 'question', 'placeholder', 'helper',
  'note', 'cta', 'image', 'video', 'poster', 'eyebrowImage', 'logoImage',
  'awardImage', 'disclaimer', 'templatesTitle', 'templatesMedia', 'rating', 'ratingSub',
  'supportEmail', 'ctaUrl', 'counterLabel', 'mediaTitle',
  'countdownMin',
];
// mảng string — 1 dòng 1 mục. logos (trust) nhận URL ảnh hoặc text;
// tasks/checklist (loading) = các câu analyze.
const EDITABLE_ARRAYS = ['options', 'benefits', 'fullAccess', 'footerLinks', 'logos', 'tasks', 'checklist'];
// block phức tạp (paywall) — sửa dạng JSON
const EDITABLE_JSON = ['plans', 'moneyBack'];
// nhãn to hơn cho field dài
const TALL_FIELDS = new Set(['title', 'question', 'body', 'subtitle', 'helper', 'disclaimer']);
// field media — có 2 nút: ⬆ tải lên ngay (auto đẩy S3/kho) · 🗂 lấy từ kho asset
const MEDIA_FIELDS = new Set(['image', 'video', 'poster', 'eyebrowImage', 'logoImage', 'awardImage', 'templatesMedia']);

export function initEditor() {
  const params = new URLSearchParams(location.search);
  if (params.get('editor') !== '1') return;
  const funnelId = params.get('funnel') || 'reunion';

  // Parent page's own funnel render is replaced by the phone-framed preview.
  const app = document.getElementById('app');
  if (app) app.style.display = 'none';
  document.body.style.overflow = 'hidden';

  const stageRef = buildStage(funnelId);
  // Live accessor — the iframe is re-created on device switch, so always read
  // it through stageRef; fall back to the last good runtime during reloads.
  const getRt = () => {
    try { return stageRef.iframe?.contentWindow?.__funnelRT?.(); } catch { return null; }
  };
  const tryMount = () => {
    const rt = getRt();
    if (!rt || !rt.funnel) return setTimeout(tryMount, 150);
    let last = rt;
    mount(() => {
      const r = getRt();
      if (r && r.funnel) last = r;
      return last;
    });
  };
  tryMount();
}

// Centered device frame (default iPhone 13) + browser-bar mock + iframe.
function buildStage(funnelId) {
  const stage = document.createElement('div');
  stage.id = 'editor-stage';
  stage.style.cssText =
    `position:fixed;top:0;left:0;right:${DRAWER_W}px;bottom:0;z-index:50;` +
    'display:flex;align-items:center;justify-content:center;flex-direction:column;gap:10px;' +
    'background:radial-gradient(1200px 700px at 50% 30%, #1a1c24 0%, #0c0d12 70%)';
  document.body.appendChild(stage);

  const holder = { iframe: null };
  const device = () =>
    DEVICES.find((d) => d.id === (localStorage.getItem(DEVICE_KEY) || 'iphone-13')) || DEVICES[3];

  const renderFrame = () => {
    const dv = device();
    stage.innerHTML = '';
    const frame = document.createElement('div');
    frame.style.cssText =
      `width:${dv.w}px;height:${dv.h}px;position:relative;flex:none;display:flex;flex-direction:column;` +
      'border-radius:47px;border:10px solid #17181c;overflow:hidden;background:#000;' +
      'box-shadow:0 24px 80px rgba(0,0,0,.6),0 0 0 1px #2a2c33';

    // browser chrome mock — the funnel is a WEB page, real users see a tab bar
    const bar = document.createElement('div');
    bar.style.cssText =
      `height:${BROWSER_BAR_H}px;flex:none;background:#1d1f26;border-bottom:1px solid #2a2c33;` +
      'display:flex;align-items:center;gap:8px;padding:0 12px;padding-top:14px';
    bar.innerHTML = `
      <span style="width:8px;height:8px;border-radius:50%;background:#3c4150"></span>
      <div style="flex:1;height:26px;border-radius:13px;background:#12141a;color:#6d7280;
                  font:11px ui-monospace,Menlo,monospace;display:flex;align-items:center;justify-content:center">
        (Browser tab here) · app.artimind.com/${escAttr(funnelId)}
      </div>
      <span style="color:#6d7280;font-size:13px">⋯</span>`;

    const iframe = document.createElement('iframe');
    const q = new URLSearchParams(location.search);
    q.delete('editor');
    q.set('funnel', funnelId);
    q.set('edpreview', '1'); // muted tracking inside the preview
    iframe.src = `${location.pathname}?${q}`;
    iframe.style.cssText = `width:${dv.w}px;height:${dv.h - BROWSER_BAR_H}px;border:0;display:block;background:#000;flex:none`;
    holder.iframe = iframe;

    frame.append(bar, iframe);

    // device picker + label under the frame
    const controls = document.createElement('div');
    controls.style.cssText = 'display:flex;align-items:center;gap:8px;flex:none';
    const sel = document.createElement('select');
    sel.style.cssText =
      'background:#181b22;color:#dfe3ec;border:1px solid #2a2f3a;border-radius:8px;padding:4px 8px;font-size:12px';
    sel.innerHTML = DEVICES.map(
      (d) => `<option value="${d.id}" ${d.id === dv.id ? 'selected' : ''}>${d.label} · ${d.w}×${d.h}</option>`,
    ).join('');
    sel.onchange = () => {
      localStorage.setItem(DEVICE_KEY, sel.value);
      renderFrame(); // re-mount preview at the new viewport
    };
    controls.append(sel);
    stage.append(frame, controls);

    // Scale the frame down (keeping proportions) when the stage is too small.
    const fit = () => {
      const pad = 36;
      const s = Math.min(
        1,
        (stage.clientHeight - pad - 30) / (dv.h + 20),
        (stage.clientWidth - pad) / (dv.w + 20),
      );
      frame.style.transform = `scale(${s})`;
      frame.style.transformOrigin = 'center center';
      frame.style.marginTop = s < 1 ? `${-((dv.h + 20) * (1 - s)) / 2}px` : '0';
      frame.style.marginBottom = s < 1 ? `${-((dv.h + 20) * (1 - s)) / 2}px` : '0';
    };
    fit();
    window.addEventListener('resize', fit);
  };

  renderFrame();
  return {
    stage,
    get iframe() { return holder.iframe; },
  };
}

function escAttr(s) {
  return String(s).replace(/[<>"']/g, '');
}

function mount(rt) {
  const funnel = rt().funnel;
  const overrides = {}; // screenId → {field: value} (edits made this session)
  let selIdx = rt().currentIndex();

  const drawer = document.createElement('aside');
  drawer.id = 'funnel-editor';
  drawer.style.cssText =
    `position:fixed;top:0;right:0;bottom:0;width:${DRAWER_W}px;z-index:70;background:#101014;color:#e8e8ea;` +
    'font:12px/1.5 ui-monospace,Menlo,monospace;border-left:1px solid #2a2a30;display:flex;flex-direction:column';
  drawer.innerHTML = `
    <header style="padding:10px 12px;border-bottom:1px solid #2a2a30">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:8px">
        <strong>✏️ Funnel Editor</strong>
        <span style="display:flex;gap:6px;align-items:center">
          <button data-ed-save title="Ghi funnel JSON" style="background:#1f9d55;border:none;color:#fff;padding:4px 12px;border-radius:7px;cursor:pointer;font-weight:700">💾 Save</button>
          <button data-ed-export title="Copy link preview ?rc=" style="background:#6b4fd8;border:none;color:#fff;padding:4px 12px;border-radius:7px;cursor:pointer;font-weight:700">🔗 Export</button>
          <button data-ed-close style="background:none;border:none;color:#888;cursor:pointer">✕</button>
        </span>
      </div>
      <div style="color:#9a9aa2;margin-top:2px">
        funnel <b style="color:#ffc73b">${esc(funnel.funnelId || funnel.id)}</b>
        ${funnel.templateId ? ` · concept <b>${esc(funnel.conceptId)}</b> · style <b>${esc(funnel.styleId || '—')}</b>` : ' · standalone'}
      </div>
    </header>
    <div style="display:flex;gap:6px;padding:8px 12px;border-bottom:1px solid #2a2a30;flex-wrap:wrap">
      <input data-ed-clone-id placeholder="clone id (vd: reunion-var-b)" style="flex:1;min-width:120px;background:#1a1a20;border:1px solid #33333a;color:#eee;padding:4px 6px;border-radius:6px">
      <input data-ed-clone-owner placeholder="mkter" style="width:70px;background:#1a1a20;border:1px solid #33333a;color:#eee;padding:4px 6px;border-radius:6px">
      <input data-ed-clone-style placeholder="style" style="width:70px;background:#1a1a20;border:1px solid #33333a;color:#eee;padding:4px 6px;border-radius:6px">
      <button data-ed-clone style="background:#2d6cdf;border:none;color:#fff;padding:4px 10px;border-radius:6px;cursor:pointer">Clone as…</button>
    </div>
    <nav data-ed-screens style="max-height:24dvh;overflow-y:auto;border-bottom:1px solid #2a2a30"></nav>
    <section data-ed-fields style="flex:1;overflow-y:auto;padding:10px 12px"></section>
    <div data-ed-msg style="padding:2px 12px;color:#9a9aa2;min-height:18px"></div>
    <footer style="padding:10px 12px;border-top:1px solid #2a2a30">
      <button data-ed-apply style="width:100%;background:#33333a;border:1px solid #44444d;color:#fff;padding:9px 0;border-radius:9px;cursor:pointer;font-weight:700">⚡ Apply (preview)</button>
    </footer>
  `;
  document.body.appendChild(drawer);

  const msg = (t, ok) => {
    const el = drawer.querySelector('[data-ed-msg]');
    el.textContent = t;
    el.style.color = ok ? '#5ad18a' : '#e8b34b';
  };

  const screensNav = drawer.querySelector('[data-ed-screens]');
  const fieldsBox = drawer.querySelector('[data-ed-fields]');
  const screens = () => rt().screens;

  const renderNav = () => {
    screensNav.innerHTML = screens()
      .map(
        (s, i) => `
      <div data-ed-nav="${i}" style="padding:6px 12px;cursor:pointer;display:flex;gap:8px;align-items:center;
           ${i === selIdx ? 'background:#1d1d26;border-left:3px solid #ffc73b' : 'border-left:3px solid transparent'}">
        <span style="color:#666;width:18px">${i + 1}</span>
        <span style="flex:1">${esc(s.id)}${overrides[s.id] ? ' <b style="color:#ffc73b">●</b>' : ''}</span>
        <span style="color:#7a7a85">${esc(s.type)}</span>
      </div>`,
      )
      .join('');
    screensNav.querySelectorAll('[data-ed-nav]').forEach((el) => {
      el.onclick = () => {
        selIdx = Number(el.dataset.edNav);
        rt().render(selIdx);
        renderNav();
        renderFields();
      };
    });
  };

  const taStyle = 'width:100%;background:#1a1a20;border:1px solid #33333a;color:#eee;padding:6px 8px;border-radius:6px;resize:vertical;font:12px/1.5 ui-monospace,Menlo,monospace';
  const rowsFor = (f, v) => {
    const len = String(v ?? '').length;
    const min = TALL_FIELDS.has(f) ? 2 : 1;
    return Math.max(min, Math.min(6, Math.ceil(len / 36)));
  };

  const renderFields = () => {
    const s = screens()[selIdx];
    if (!s) { fieldsBox.innerHTML = ''; return; }
    const rows = [];

    // insert screens: chọn 1 trong 2 dạng + validate copy (operator 2026-07-03)
    if (s.type === 'engagement-insert') {
      const isEmail = (s.inputType || 'text') === 'email';
      rows.push(`
        <div style="display:flex;gap:10px;align-items:center;margin-bottom:10px;padding:8px;border:1px solid #33333a;border-radius:8px">
          <label style="color:#8a8a92">Dạng màn:
            <select data-ed-insert-variant style="background:#1a1a20;border:1px solid #33333a;color:#eee;border-radius:6px;padding:3px 6px;margin-left:4px">
              <option value="message" ${!isEmail ? 'selected' : ''}>insert-message</option>
              <option value="email" ${isEmail ? 'selected' : ''}>insert-email</option>
            </select>
          </label>
          <label style="color:#8a8a92;display:flex;align-items:center;gap:4px">
            <input type="checkbox" data-ed-required ${s.optional ? '' : 'checked'}> Bắt buộc nhập
          </label>
        </div>
        <label style="display:block;margin-bottom:8px">
          <span style="color:#8a8a92">Câu validate khi CHƯA nhập (emptyError)</span>
          <textarea data-ed-f="emptyError" rows="${rowsFor('emptyError', s.emptyError)}" style="${taStyle}">${esc(String(s.emptyError ?? ''))}</textarea>
        </label>
        <label style="display:block;margin-bottom:8px">
          <span style="color:#8a8a92">Câu validate khi nhập SAI (invalidError${isEmail ? ' — email' : ''})</span>
          <textarea data-ed-f="invalidError" rows="${rowsFor('invalidError', s.invalidError)}" style="${taStyle}">${esc(String(s.invalidError ?? ''))}</textarea>
        </label>`);
    }

    // paywall: giá = CHỌN Price ID từ funnel-monkey (Stripe là phương thức
    // chính — operator 2026-07-03). 3 slot week/month/year, mỗi slot 1 offer
    // item; danh sách load async từ /__funnel/monkey/offer.
    if (s.type === 'paywall') {
      const cur = Object.fromEntries((s.plans || []).map((pl) => [pl.id, pl]));
      rows.push(`
        <div data-ed-monkey style="margin-bottom:10px;padding:8px;border:1px solid #33333a;border-radius:8px">
          <div style="color:#ffc73b;font-weight:700;margin-bottom:6px">💳 Giá — funnel-monkey (Stripe)</div>
          <div data-ed-monkey-status style="color:#8a8a92;margin-bottom:6px">Đang tải offer…</div>
          ${['week', 'month', 'year'].map((slot) => `
            <label style="display:block;margin-bottom:6px">
              <span style="color:#8a8a92;text-transform:capitalize">${slot}</span>
              <select data-ed-price="${slot}" data-current="${esc(cur[slot]?.offerItemId || '')}"
                style="width:100%;background:#1a1a20;border:1px solid #33333a;color:#eee;padding:5px 6px;border-radius:6px">
                <option value="">— đang tải —</option>
              </select>
            </label>`).join('')}
          <div style="color:#5b5b64;font-size:11px">Chọn Price ID → Apply. Giá hiển thị + checkout lấy đúng offer item đã chọn.</div>
        </div>`);
    }

    for (const f of EDITABLE) {
      if (s[f] === undefined && !ALWAYS_FIELDS.includes(f)) continue;
      const mediaBtns = MEDIA_FIELDS.has(f)
        ? `<span style="float:right;display:inline-flex;gap:4px">
             <button type="button" data-ed-upload="${f}" title="Tải file lên ngay (tự đẩy S3/kho)"
               style="background:#2d6cdf;border:none;color:#fff;padding:1px 8px;border-radius:5px;cursor:pointer;font-size:11px">⬆ Tải lên</button>
             <button type="button" data-ed-lib="${f}" title="Chọn từ kho creative"
               style="background:#33333a;border:none;color:#ddd;padding:1px 8px;border-radius:5px;cursor:pointer;font-size:11px">🗂 Kho</button>
           </span>`
        : '';
      rows.push(`
        <label style="display:block;margin-bottom:8px">
          <span style="color:#8a8a92">${f}</span>${mediaBtns}
          <textarea data-ed-f="${f}" rows="${rowsFor(f, s[f])}" style="${taStyle}">${esc(String(s[f] ?? ''))}</textarea>
        </label>`);
    }
    for (const f of EDITABLE_ARRAYS) {
      // trust: logos luôn hiện (setup tên hãng dạng ẢNH — dán URL mỗi dòng)
      const always = (s.type === 'trust' && f === 'logos') || (s.type === 'loading' && (f === 'tasks'));
      if (!Array.isArray(s[f]) && !always) continue;
      const val = Array.isArray(s[f]) ? s[f] : [];
      const hint = f === 'logos' ? ' — ẢNH hãng (Forbes, USA Today…), mỗi dòng 1 URL' : f === 'tasks' || f === 'checklist' ? ' — câu analyze, mỗi dòng 1 câu' : ' (mỗi dòng 1 mục)';
      const arrBtns = f === 'logos'
        ? `<span style="float:right;display:inline-flex;gap:4px">
             <button type="button" data-ed-upload-arr="${f}" title="Tải ảnh hãng lên (append 1 dòng)"
               style="background:#2d6cdf;border:none;color:#fff;padding:1px 8px;border-radius:5px;cursor:pointer;font-size:11px">⬆ Thêm ảnh</button>
             <button type="button" data-ed-lib-arr="${f}" title="Chọn từ kho (append 1 dòng)"
               style="background:#33333a;border:none;color:#ddd;padding:1px 8px;border-radius:5px;cursor:pointer;font-size:11px">🗂 Kho</button>
           </span>`
        : '';
      rows.push(`
        <label style="display:block;margin-bottom:8px">
          <span style="color:#8a8a92">${f}${hint}</span>${arrBtns}
          <textarea data-ed-fa="${f}" rows="${Math.max(2, Math.min(7, val.length + 1))}" style="${taStyle}">${esc(val.join('\n'))}</textarea>
        </label>`);
    }
    // paywall: mọi block chỉnh được — block phức tạp sửa dạng JSON
    for (const f of EDITABLE_JSON) {
      if (s[f] === undefined && s.type !== 'paywall') continue;
      const val = s[f] !== undefined ? JSON.stringify(s[f], null, 1) : '';
      rows.push(`
        <label style="display:block;margin-bottom:8px">
          <span style="color:#8a8a92">${f} (JSON)</span>
          <textarea data-ed-fj="${f}" rows="${Math.max(3, Math.min(10, val.split('\n').length))}" style="${taStyle}">${esc(val)}</textarea>
        </label>`);
    }
    fieldsBox.innerHTML = `
      <div style="color:#ffc73b;font-weight:700;margin-bottom:8px">${esc(s.id)} · ${esc(s.type)}</div>
      ${rows.join('') || '<p style="color:#666">Màn này không có field editable.</p>'}
    `;
    if (s.type === 'paywall') loadMonkeyOffer();
    bindMediaButtons();
  };

  // ---- Kho creative: upload ngay / chọn từ kho (operator 2026-07-03) ----
  function bindMediaButtons() {
    fieldsBox.querySelectorAll('[data-ed-upload]').forEach((b) => {
      b.onclick = () => {
        const f = b.dataset.edUpload;
        const inp = document.createElement('input');
        inp.type = 'file';
        inp.accept = f === 'video' ? 'video/*' : 'image/*,video/*';
        inp.onchange = async () => {
          const file = inp.files?.[0];
          if (!file) return;
          b.textContent = '⏳';
          try {
            const dataBase64 = await new Promise((ok, err) => {
              const r = new FileReader();
              r.onload = () => ok(String(r.result).split(',')[1]);
              r.onerror = err;
              r.readAsDataURL(file);
            });
            const res = await fetch('/__funnel/assets', {
              method: 'POST',
              body: JSON.stringify({ name: file.name, type: file.type.startsWith('video') ? 'video' : 'image', dataBase64 }),
            });
            const body = await res.json();
            if (!res.ok) throw new Error(body.error || res.status);
            const ta = fieldsBox.querySelector(`[data-ed-f="${f}"]`);
            ta.value = body.asset.url;
            msg(`⬆ ${body.asset.name} → ${body.asset.storage === 's3' ? 'S3' : 'kho bundle'}${body.dedupe ? ' (đã có sẵn)' : ''}. Bấm Apply để xem.`, true);
          } catch (e) {
            msg(`Upload lỗi: ${e.message}`);
          }
          b.textContent = '⬆ Tải lên';
        };
        inp.click();
      };
    });
    fieldsBox.querySelectorAll('[data-ed-lib]').forEach((b) => {
      b.onclick = () => openAssetLibrary(b.dataset.edLib);
    });
    // array media (logos): append 1 dòng URL vào textarea
    const appendLine = (f, url) => {
      const ta = fieldsBox.querySelector(`[data-ed-fa="${f}"]`);
      if (!ta) return;
      ta.value = (ta.value.trim() ? ta.value.trim() + '\n' : '') + url;
    };
    fieldsBox.querySelectorAll('[data-ed-upload-arr]').forEach((b) => {
      b.onclick = () => {
        const f = b.dataset.edUploadArr;
        const inp = document.createElement('input');
        inp.type = 'file'; inp.accept = 'image/*';
        inp.onchange = async () => {
          const file = inp.files?.[0];
          if (!file) return;
          b.textContent = '⏳';
          try {
            const dataBase64 = await new Promise((ok, err) => {
              const r = new FileReader();
              r.onload = () => ok(String(r.result).split(',')[1]);
              r.onerror = err; r.readAsDataURL(file);
            });
            const res = await fetch('/__funnel/assets', { method: 'POST',
              body: JSON.stringify({ name: file.name, type: 'image', dataBase64 }) });
            const body = await res.json();
            if (!res.ok) throw new Error(body.error || res.status);
            appendLine(f, body.asset.url);
            msg(`⬆ ${body.asset.name} → ${body.asset.storage === 's3' ? 'S3' : 'kho bundle'}. Apply để xem.`, true);
          } catch (e) { msg(`Upload lỗi: ${e.message}`); }
          b.textContent = '⬆ Thêm ảnh';
        };
        inp.click();
      };
    });
    fieldsBox.querySelectorAll('[data-ed-lib-arr]').forEach((b) => {
      b.onclick = () => openAssetLibrary(b.dataset.edLibArr, (url) => appendLine(b.dataset.edLibArr, url));
    });
  }

  async function openAssetLibrary(field, onPick) {
    let assets = [];
    try { assets = (await (await fetch('/__funnel/assets')).json()).assets || []; } catch { /* dev only */ }
    const wantVideo = field === 'video';
    const list = assets.filter((a) => (wantVideo ? a.type === 'video' : true));
    const overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;inset:0;z-index:90;background:rgba(0,0,0,.65);display:flex;align-items:center;justify-content:center';
    overlay.innerHTML = `
      <div style="width:640px;max-width:94vw;max-height:80dvh;overflow-y:auto;background:#14161d;border:1px solid #262b38;border-radius:14px;padding:16px;color:#e8e8ea;font:12px ui-monospace,Menlo,monospace">
        <div style="display:flex;align-items:center;margin-bottom:10px">
          <b>🗂 Kho creative — chọn cho "${esc(field)}"</b>
          <input data-lib-q placeholder="lọc theo tên…" style="margin-left:12px;flex:1;background:#1a1a20;border:1px solid #33333a;color:#eee;padding:4px 8px;border-radius:6px">
          <button data-lib-x style="margin-left:8px;background:none;border:none;color:#888;cursor:pointer;font-size:15px">✕</button>
        </div>
        <div data-lib-grid style="display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:8px">
          ${list.map((a) => `
            <div data-lib-pick="${esc(a.url)}" title="${esc(a.name)} · ${(a.size / 1024).toFixed(0)}KB · ${esc(a.storage)}"
                 style="cursor:pointer;border:1px solid #2a2a30;border-radius:8px;overflow:hidden;background:#0e0f14" data-lib-name="${esc(a.name.toLowerCase())}">
              ${a.type === 'video'
                ? `<div style="height:80px;display:flex;align-items:center;justify-content:center;font-size:26px">🎬</div>`
                : `<img src="${esc(a.url)}" style="width:100%;height:80px;object-fit:cover" loading="lazy">`}
              <div style="padding:3px 6px;color:#9a9aa2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(a.name)}</div>
            </div>`).join('') || '<p style="color:#666;grid-column:1/-1">Kho trống — dùng ⬆ Tải lên trước.</p>'}
        </div>
      </div>`;
    document.body.appendChild(overlay);
    overlay.querySelector('[data-lib-x]').onclick = () => overlay.remove();
    overlay.addEventListener('click', (e) => { if (e.target === overlay) overlay.remove(); });
    overlay.querySelector('[data-lib-q]').oninput = (e) => {
      const q = e.target.value.toLowerCase();
      overlay.querySelectorAll('[data-lib-pick]').forEach((c) => {
        c.style.display = c.dataset.libName.includes(q) ? '' : 'none';
      });
    };
    overlay.querySelectorAll('[data-lib-pick]').forEach((c) => {
      c.onclick = () => {
        if (onPick) onPick(c.dataset.libPick);
        else {
          const ta = fieldsBox.querySelector(`[data-ed-f="${field}"]`);
          if (ta) ta.value = c.dataset.libPick;
        }
        overlay.remove();
        msg(`🗂 Đã chọn asset cho ${field}. Bấm Apply để xem.`, true);
      };
    });
  }

  // Load offer items từ funnel-monkey (qua dev proxy) và đổ vào 3 select slot.
  let monkeyItems = [];
  async function loadMonkeyOffer() {
    const status = fieldsBox.querySelector('[data-ed-monkey-status]');
    if (!status) return;
    try {
      const r = await fetch(`/__funnel/monkey/offer?funnel=${encodeURIComponent(funnel.funnelId || funnel.id)}`);
      const b = await r.json();
      if (!r.ok) throw new Error(b.error || r.status);
      monkeyItems = b.items || [];
      status.innerHTML = b.mock
        ? `<span style="color:#e8b34b">⚠ MOCK offer</span> — ${esc(b.reason || '')}`
        : `✓ Offer <b>${esc(b.offerName || '')}</b> · ${monkeyItems.length} price`;
      fieldsBox.querySelectorAll('[data-ed-price]').forEach((sel) => {
        const slot = sel.dataset.edPrice;
        const current = sel.dataset.current;
        // gợi ý mặc định theo interval khớp slot
        const opts = ['<option value="">— không dùng slot này —</option>']
          .concat(monkeyItems.map((it) =>
            `<option value="${esc(it.offerItemId)}" ${it.offerItemId === current ? 'selected' : ''}>` +
            `${esc(it.name)} · ${esc(it.formatted)}/${esc(it.interval)}${it.priceId ? ` · ${esc(it.priceId)}` : ''}</option>`));
        sel.innerHTML = opts.join('');
        if (!current) {
          const match = monkeyItems.find((it) => it.interval.startsWith(slot));
          if (match) sel.value = match.offerItemId;
        }
      });
    } catch (e) {
      status.innerHTML = `<span style="color:#f8545d">✗ ${esc(String(e.message || e))}</span>`;
    }
  }

  // Build plans[] từ 3 slot Price ID đã chọn.
  const SLOT_META = {
    week: { label: 'Weekly', period: '/wk', featured: true, badge: '🔥 MOST POPULAR' },
    month: { label: 'Monthly', period: '/mo' },
    year: { label: 'Yearly', period: '/yr' },
  };
  function plansFromPicker() {
    const sels = [...fieldsBox.querySelectorAll('[data-ed-price]')];
    if (!sels.length) return null;
    const plans = [];
    for (const sel of sels) {
      if (!sel.value) continue;
      const it = monkeyItems.find((x) => x.offerItemId === sel.value);
      if (!it) continue;
      const slot = sel.dataset.edPrice;
      plans.push({
        id: slot,
        ...SLOT_META[slot],
        price: it.formatted,
        offerItemId: it.offerItemId,
        priceId: it.priceId || undefined,
      });
    }
    return plans.length ? plans : null;
  }

  // Apply — nút ghim ở footer (luôn ở góc dưới, operator 2026-07-03)
  drawer.querySelector('[data-ed-apply]').onclick = () => {
    const s = screens()[selIdx];
    if (!s) return;
    const patch = {};
    fieldsBox.querySelectorAll('[data-ed-f]').forEach((ta) => {
      const f = ta.dataset.edF;
      let v = ta.value;
      if (f === 'countdownMin') v = Number(v) || 0;
      if (String(s[f] ?? '') !== String(v)) patch[f] = v;
    });
    fieldsBox.querySelectorAll('[data-ed-fa]').forEach((ta) => {
      const f = ta.dataset.edFa;
      const v = ta.value.split('\n').map((x) => x.trim()).filter(Boolean);
      if (JSON.stringify(s[f] ?? []) !== JSON.stringify(v)) patch[f] = v;
    });
    for (const ta of fieldsBox.querySelectorAll('[data-ed-fj]')) {
      const f = ta.dataset.edFj;
      const raw = ta.value.trim();
      if (!raw) continue;
      try {
        const v = JSON.parse(raw);
        if (JSON.stringify(s[f]) !== JSON.stringify(v)) patch[f] = v;
      } catch (e) {
        return msg(`JSON lỗi ở "${f}": ${e.message}`);
      }
    }
    // paywall: plans từ picker Price ID (funnel-monkey)
    const picked = plansFromPicker();
    if (picked) {
      const cur = JSON.stringify((s.plans || []).map((pl) => pl.offerItemId || pl.id));
      const nxt = JSON.stringify(picked.map((pl) => pl.offerItemId));
      if (cur !== nxt) patch.plans = picked;
    }
    // insert variant + required
    const variant = fieldsBox.querySelector('[data-ed-insert-variant]');
    if (variant) {
      const it = variant.value === 'email' ? 'email' : 'text';
      if (it !== (s.inputType || 'text')) patch.inputType = it;
      const required = fieldsBox.querySelector('[data-ed-required]').checked;
      if (!!s.optional !== !required) patch.optional = !required;
    }
    if (!Object.keys(patch).length) return msg('Không có thay đổi.');
    overrides[s.id] = { ...(overrides[s.id] || {}), ...patch };
    rt().applyScreenPatch(s.id, patch);
    renderNav();
    msg(`Applied ${Object.keys(patch).length} field(s) → màn ${s.id}.`, true);
  };

  // Session edits MERGE over the funnel's EXISTING overrides (per screen id).
  // Without this, Save would wipe content saved in earlier sessions (bug
  // caught 2026-07-03: reunion-var-a lost its copy overrides).
  const buildDef = (id, owner, style) => {
    const existing = FUNNELS[funnel.funnelId || funnel.id]?.overrides || {};
    const byId = {};
    for (const s of existing.screens || []) {
      if (s?.id) byId[s.id] = { ...s };
    }
    for (const [sid, patch] of Object.entries(overrides)) {
      byId[sid] = { ...(byId[sid] || { id: sid }), ...patch };
    }
    const srcDef = FUNNELS[funnel.funnelId || funnel.id] || {};
    return {
      id,
      template: funnel.templateId || undefined,
      style: style || funnel.styleId || undefined,
      owner: owner || funnel.owner || undefined,
      vendor: srcDef.vendor || funnel.vendor || undefined, // pixel kế thừa từ funnel gốc
      overrides: { ...existing, screens: Object.values(byId) },
    };
  };

  drawer.querySelector('[data-ed-save]').onclick = async () => {
    // TEMPLATE mode: ?funnel=tpl:<id> → ghi thẳng vào TEMPLATE (save-template),
    // giữ metadata (status/assigned/role/steps/product), apply edit theo screen id.
    const fp = new URLSearchParams(location.search).get('funnel') || '';
    if (fp.startsWith('tpl:')) {
      const tplId = fp.slice(4);
      const base = TEMPLATES[tplId];
      if (!base) return msg('Template không tìm thấy.');
      const tpl = JSON.parse(JSON.stringify(base));
      const byId = {}; (tpl.screens || []).forEach((s) => { if (s?.id) byId[s.id] = s; });
      for (const [sid, patch] of Object.entries(overrides)) byId[sid] = { ...(byId[sid] || { id: sid }), ...patch };
      tpl.screens = (tpl.screens || []).map((s) => byId[s.id] || s);
      try {
        const r = await fetch('/__funnel/save-template', { method: 'POST', body: JSON.stringify(tpl) });
        const b = await r.json();
        if (!r.ok) throw new Error(b.error || r.status);
        msg(`Template saved → ${b.file}${b.synced?.length ? ` · sync ${b.synced.length} funnel` : ''}`, true);
      } catch (e) { msg(`Save lỗi: ${e.message}`); }
      return;
    }
    const def = buildDef(funnel.funnelId || funnel.id);
    try {
      const r = await fetch('/__funnel/save', { method: 'POST', body: JSON.stringify(def) });
      const b = await r.json();
      if (!r.ok) throw new Error(b.error || r.status);
      msg(`Saved → ${b.file}`, true);
    } catch (e) {
      msg(`Save lỗi: ${e.message} (dev server only)`);
    }
  };

  drawer.querySelector('[data-ed-clone]').onclick = async () => {
    const raw = drawer.querySelector('[data-ed-clone-id]').value.trim();
    // Auto-slugify: hạ chữ thường + thay ký tự lạ bằng '-' (id yêu cầu a-z0-9-).
    const id = raw.toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '');
    const owner = drawer.querySelector('[data-ed-clone-owner]').value.trim();
    const style = drawer.querySelector('[data-ed-clone-style]').value.trim();
    if (!id) return msg('Nhập clone id trước.');
    if (id !== raw) drawer.querySelector('[data-ed-clone-id]').value = id; // cho user thấy slug đã chuẩn hoá
    if (FUNNELS[id]) return msg(`Funnel "${id}" đã tồn tại.`);
    if (!funnel.templateId) return msg('Funnel standalone — không có template để clone.');
    const def = buildDef(id, owner, style);
    try {
      const r = await fetch('/__funnel/save', { method: 'POST', body: JSON.stringify(def) });
      const b = await r.json();
      if (!r.ok) throw new Error(b.error || r.status);
      msg(`Clone saved → ${b.file}. Mở ?funnel=${id}&editor=1`, true);
      setTimeout(() => { location.search = `?funnel=${id}&editor=1`; }, 900);
    } catch (e) {
      msg(`Clone lỗi: ${e.message}`);
    }
  };

  drawer.querySelector('[data-ed-export]').onclick = () => {
    const ov = { screens: Object.entries(overrides).map(([sid, patch]) => ({ id: sid, ...patch })) };
    const rc = btoa(unescape(encodeURIComponent(JSON.stringify(ov))));
    const url = `${location.origin}${location.pathname}?funnel=${encodeURIComponent(funnel.funnelId || funnel.id)}&rc=${rc}`;
    navigator.clipboard?.writeText(url);
    msg('Đã copy preview link (?rc=) vào clipboard.', true);
  };

  drawer.querySelector('[data-ed-close]').onclick = () => {
    drawer.remove();
    document.getElementById('editor-stage')?.remove();
    document.body.style.overflow = '';
    const app = document.getElementById('app');
    if (app) app.style.display = '';
  };

  renderNav();
  renderFields();
  // available templates hint (Huy's catalog)
  console.info('[editor] templates:', Object.keys(TEMPLATES), '· funnels:', Object.keys(FUNNELS));
}

function esc(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
}
