// Loading — original funnel structure (operator 2026-06-12): title + subtitle,
// hero media, then PER-TASK progress rows (label + bar + % counting to 100,
// sequential). Falls back to the simple spinner+checklist when no `tasks`.

export function loading(screen, advance) {
  const root = document.createElement('section');
  root.className = 'flex h-full min-h-0 flex-1 flex-col gap-4 py-2';
  const tasks = screen.tasks || screen.checklist || [];
  const duration = Number.isFinite(screen.durationMs) ? screen.durationMs : 4000;

  root.innerHTML = `
    ${
      screen.eyebrowImage
        ? `<img src="${escapeAttr(screen.eyebrowImage)}" alt="" class="eyebrow-img mx-auto w-auto shrink-0 object-contain" />`
        : ''
    }
    <header class="flex shrink-0 flex-col gap-1.5 text-center">
      <h2 class="t-title t-screen-title font-bold">${escapeHtml(screen.title || 'Đang chuẩn bị cho bạn…')}</h2>
      ${screen.body ? `<p class="t-muted t-body">${escapeHtml(screen.body)}</p>` : ''}
    </header>
    <div class="card-surface min-h-0 flex-1 overflow-hidden rounded-2xl">
      ${mediaBlock(screen)}
    </div>
    <div class="flex shrink-0 flex-col gap-3 pb-2" data-tasks>
      ${tasks
        .map(
          (t, i) => `
        <div class="flex flex-col gap-1.5" data-task="${i}">
          <div class="t-body flex items-center justify-between gap-2">
            <span class="t-title font-semibold">${escapeHtml(t)}</span>
            <span class="t-muted font-mono" data-pct>0%</span>
          </div>
          <div class="loading-bar-track"><div class="loading-bar-fill" data-fill></div></div>
        </div>`,
        )
        .join('')}
    </div>
  `;

  const params = new URLSearchParams(location.search);
  const blockAdvance = params.has('nostep');
  const rows = [...root.querySelectorAll('[data-task]')];

  if (rows.length) {
    const per = duration / rows.length;
    const animateRow = (i) => {
      if (i >= rows.length) {
        if (!blockAdvance) setTimeout(() => advance({}), 350);
        return;
      }
      const row = rows[i];
      const pctEl = row.querySelector('[data-pct]');
      const fillEl = row.querySelector('[data-fill]');
      const t0 = performance.now();
      const tick = (now) => {
        const p = Math.min(1, (now - t0) / per);
        const pct = Math.floor(p * 100);
        pctEl.textContent = `${pct}%`;
        fillEl.style.width = `${pct}%`;
        if (p < 1) requestAnimationFrame(tick);
        else {
          pctEl.textContent = '100% ✅';
          animateRow(i + 1);
        }
      };
      requestAnimationFrame(tick);
    };
    animateRow(0);
  } else if (!blockAdvance) {
    setTimeout(() => advance({}), duration);
  }
  return root;
}

function mediaBlock(screen) {
  if (screen.video) {
    return `<video src="${escapeAttr(screen.video)}" autoplay muted loop playsinline data-media
                   class="h-full w-full object-cover"></video>`;
  }
  if (screen.image) {
    return `<img src="${escapeAttr(screen.image)}" alt="" data-media class="h-full w-full object-cover" />`;
  }
  return `<div class="flex h-full items-center justify-center">
    <div class="h-14 w-14 animate-spin rounded-full border-4"
         style="border-color: var(--c-border); border-top-color: var(--c-gold)"></div>
  </div>`;
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
}

function escapeAttr(s) {
  return String(s).replace(/["']/g, (c) => ({ '"': '&quot;', "'": '&#39;' })[c]);
}
