// Facebook-post testimonial carousel (reunion screen 09 original) — scroll-snap
// slides + dots + gentle auto-advance. Images mirrored locally (resized webp);
// TODO move to team S3 when creds available.

export function testimonialCarousel(screen, advance) {
  const root = document.createElement('section');
  root.className = 'flex h-full min-h-0 flex-1 flex-col gap-4 py-2';
  const images = screen.images || [];

  root.innerHTML = `
    ${
      screen.eyebrowImage
        ? `<img src="${escapeAttr(screen.eyebrowImage)}" alt="" class="eyebrow-img mx-auto w-auto shrink-0 object-contain" />`
        : ''
    }
    <header class="shrink-0 text-center">
      <h1 class="t-title t-screen-title font-bold">${escapeHtml(screen.title || 'Millions shared #Artimind')}</h1>
    </header>
    <div class="carousel min-h-0 flex-1 items-center" data-carousel>
      ${images
        .map(
          (src) => `
        <div class="card-surface flex h-full items-center">
          <img src="${escapeAttr(src)}" alt="Customer post" loading="lazy"
               class="max-h-full w-full object-contain" />
        </div>`,
        )
        .join('')}
    </div>
    <div class="flex shrink-0 items-center justify-center gap-2" data-dots>
      ${images.map((_, i) => `<span class="carousel-dot${i === 0 ? ' active' : ''}" data-dot="${i}"></span>`).join('')}
    </div>
    <div class="shrink-0">
      <button type="button" class="btn-primary" data-cta data-cta-pulse>${escapeHtml(screen.cta || 'Continue')}</button>
    </div>
  `;

  const car = root.querySelector('[data-carousel]');
  const dots = [...root.querySelectorAll('[data-dot]')];
  let idx = 0;
  let userTouched = false;

  const goTo = (i) => {
    idx = (i + images.length) % images.length;
    const slide = car.children[idx];
    if (slide) car.scrollTo({ left: slide.offsetLeft - 16, behavior: 'smooth' });
  };
  car.addEventListener('scroll', () => {
    const center = car.scrollLeft + car.clientWidth / 2;
    let best = 0, bestD = Infinity;
    [...car.children].forEach((el, i) => {
      const d = Math.abs(el.offsetLeft + el.clientWidth / 2 - center);
      if (d < bestD) { bestD = d; best = i; }
    });
    idx = best;
    dots.forEach((d, i) => d.classList.toggle('active', i === idx));
  }, { passive: true });
  car.addEventListener('pointerdown', () => { userTouched = true; }, { passive: true });

  if (!matchMedia('(prefers-reduced-motion: reduce)').matches) {
    const timer = setInterval(() => {
      if (!car.isConnected) return clearInterval(timer);
      if (!userTouched) goTo(idx + 1);
    }, 3200);
  }

  root.querySelector('[data-cta]').onclick = () => advance({ viewed: idx + 1 });
  return root;
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
}

function escapeAttr(s) {
  return String(s).replace(/["']/g, (c) => ({ '"': '&quot;', "'": '&#39;' })[c]);
}
