// Long-form paywall matching the live reunion funnel (operator 2026-06-12):
// countdown (pinned) → eyebrow/title → media →
// benefits → plans (per-day price tags, featured default-selected) → PAYMENT
// FORM (wallets + card + SUBSCRIBE) → Full Access Pass → 14-day money-back →
// "20 templates" rotating rings (CMS) → rating → footer.
// Everything scrolls under the always-visible cta-dock.
//
// Default prices kept in sync with `project_web2app_paywall_change_2026_06`:
//   week $9.99 · month $19.99 · year $49.99.
//
// REAL CHECKOUT (operator directive 2026-07-03 — supersedes the old
// "UI-only" rule): payments go through src/payments/ adapters —
//   card   → funnel-monkey offer + Stripe EMBEDDED checkout (wallets included)
//   paypal → PayPal subscription buttons · paddle → Paddle overlay
// When no provider is configured the mock path simulates success, so the POC
// demo (and e2e) keep working without credentials.
//
// Dynamic plans: when funnel-monkey is configured the offer's plans REPLACE
// the local config plans (funnelfox parity — dashboard changes prices, not
// deploys). Giá hiển thị = giá Stripe/offer = giá CHARGE (logic discount vòng
// xoay ĐÃ BỎ — operator 2026-07-11). Strike-through chỉ khi plan tự set `was`.

import { getState, setEmail } from '../state.js';
import { track } from '../tracking.js';
import { startCheckout, availableProviders, loadRemotePlans, hasInlineStripe, mountInlineCheckout } from '../payments/index.js';

const DEFAULT_PLANS = [
  { id: 'week', label: 'Weekly', price: '$9.99', period: '/wk', featured: true, badge: '🔥 MOST POPULAR' },
  { id: 'month', label: 'Monthly', price: '$19.99', period: '/mo' },
  { id: 'year', label: 'Yearly', price: '$49.99', period: '/yr' },
];

export function paywall(screen, advance) {
  const root = document.createElement('section');
  root.className = 'relative flex h-full min-h-0 flex-1 flex-col gap-3 py-1';
  const funnel = screen.funnel || {};
  // (logic discountPct/vòng xoay ĐÃ BỎ — operator 2026-07-11). Giá hiển thị =
  // giá Stripe/config = giá charge. Strike-through chỉ khi plan tự có `was`/oldPrice.
  let plans = normalizePlans(screen.plans?.length ? screen.plans : DEFAULT_PLANS);
  let selected = (plans.find((p) => p.featured) ?? plans[0]).id; // default selected — never blocks

  root.innerHTML = `
    ${countdownBlock(screen)}
    <div class="screen-scroll flex flex-col gap-4">
      <header class="flex flex-col gap-2 text-center">
        ${screen.eyebrowImage ? `<img src="${escapeAttr(screen.eyebrowImage)}" alt="" class="eyebrow-img mx-auto w-auto shrink-0 object-contain" />` : ''}
        ${screen.eyebrow ? `<p class="t-faint t-small font-bold uppercase tracking-widest">${escapeHtml(screen.eyebrow)}</p>` : ''}
        <h1 class="t-title t-screen-title font-bold">${escapeHtml(screen.title || 'Start your free trial')}</h1>
        ${screen.body ? `<p class="t-muted t-body">${escapeHtml(screen.body)}</p>` : ''}
      </header>
      ${
        screen.image
          ? `<img src="${escapeAttr(screen.image)}" alt="" data-media class="max-h-[24dvh] w-full rounded-2xl object-cover shadow-lg" />`
          : ''
      }
      ${
        screen.benefits?.length
          ? `<ul class="t-body flex flex-col gap-2" data-stagger>
              ${screen.benefits.map((b) => `<li class="t-muted flex items-start gap-2"><span style="color:var(--c-gold)">✓</span>${escapeHtml(b)}</li>`).join('')}
            </ul>`
          : ''
      }
      <div class="flex flex-col gap-3 pt-1" data-plans data-stagger></div>

      ${screen.payment ? paymentForm() : ''}

      ${
        screen.fullAccess?.length
          ? `<div class="flex flex-col gap-2 pt-2">
              <h2 class="t-title t-screen-title text-center font-bold">✨ Your Full Access Pass</h2>
              <ul class="t-body flex flex-col gap-2 pt-1">
                ${screen.fullAccess.map((b) => `<li class="t-title flex items-start gap-2 font-semibold"><span>✓</span>${escapeHtml(b)}</li>`).join('')}
              </ul>
            </div>`
          : ''
      }
      ${
        screen.moneyBack
          ? `<div class="flex flex-col items-center gap-2 pt-3 text-center">
              <div class="text-5xl">🛡️</div>
              <h2 class="t-title t-screen-title font-bold">${escapeHtml(screen.moneyBack.title || '14-Day Money-Back Guarantee')}</h2>
              ${screen.moneyBack.body ? `<p class="t-muted t-body">${escapeHtml(screen.moneyBack.body)}</p>` : ''}
              ${screen.moneyBack.body2 ? `<p class="t-muted t-body">${escapeHtml(screen.moneyBack.body2)}</p>` : ''}
            </div>`
          : ''
      }
      ${
        screen.templatesTitle || screen.templatesMedia
          ? `<div class="flex flex-col gap-3 pt-3">
              ${screen.templatesTitle ? `<h2 class="t-title t-screen-title text-center font-bold">${escapeHtml(screen.templatesTitle)}</h2>` : ''}
              ${templatesMediaBlock(screen)}
            </div>`
          : ''
      }
      ${
        screen.rating
          ? `<div class="flex flex-col items-center gap-1 pt-2 text-center">
              <p class="t-title t-body font-semibold">${escapeHtml(screen.rating)}</p>
              ${screen.ratingSub ? `<p class="t-title t-screen-title font-bold">${escapeHtml(screen.ratingSub)}</p>` : ''}
            </div>`
          : ''
      }
      <footer class="flex flex-col items-center gap-2 pb-4 pt-4 text-center">
        <p class="t-title text-xl font-bold">🦋 artimind</p>
        ${(screen.footerLinks || []).map((l) => `<a href="#" class="t-muted t-body underline">${escapeHtml(l)}</a>`).join('')}
        ${screen.supportEmail ? `<p class="t-faint t-small pt-1">Need help?<br/><a class="t-muted underline" href="mailto:${escapeAttr(screen.supportEmail)}">${escapeHtml(screen.supportEmail)}</a></p>` : ''}
      </footer>
    </div>

    <div class="cta-dock">
      <button type="button" class="btn-primary" data-cta data-cta-pulse>
        ${escapeHtml(screen.cta || 'Continue')}
      </button>
      <p class="t-faint pt-2 text-center text-xs">
        ${escapeHtml(screen.disclaimer || 'Cancel anytime in Settings.')}
      </p>
    </div>
  `;

  // ---- plans (re-renderable: funnel-monkey offer may replace them) ----
  const plansBox = root.querySelector('[data-plans]');
  const renderPlans = () => {
    plansBox.innerHTML = '';
    for (const p of plans) {
      const card = document.createElement('button');
      card.type = 'button';
      card.dataset.plan = p.id;
      card.className = 'relative rounded-2xl border-2 px-4 py-3.5 text-left transition';
      card.innerHTML = `
        ${p.badge ? `<div class="absolute -top-2.5 left-4 rounded-full px-2 py-0.5 text-[11px] font-bold" style="background: var(--c-gold); color: #42050A">${escapeHtml(p.badge)}</div>` : ''}
        <div class="flex items-center justify-between gap-2">
          <span data-check class="hidden h-6 w-6 shrink-0 items-center justify-center rounded-full text-sm font-bold"
                style="background: var(--c-gold); color: #42050A">✓</span>
          <div class="mr-auto">
            <div class="t-title text-base font-semibold">${escapeHtml(p.label)}</div>
            <div class="flex items-baseline gap-2">
              ${p.was ? `<span class="t-faint text-sm line-through">${escapeHtml(p.was)}</span>` : ''}
              <span class="t-title text-base font-semibold">${escapeHtml(p.price)}<span class="t-faint text-sm font-normal">${escapeHtml(p.period || '')}</span></span>
            </div>
          </div>
          ${
            p.perDay
              ? `<div class="shrink-0 rounded-lg px-3 py-1.5 text-center" data-perday
                     style="background: var(--c-surface-2); color: #fff">
                   <span class="text-lg font-extrabold">${escapeHtml(p.perDay)}</span>
                   <span class="block text-[10px] font-semibold opacity-85">per day</span>
                 </div>`
              : ''
          }
        </div>
      `;
      plansBox.appendChild(card);
    }
    updateSelection();
  };

  const updateSummary = () => {
    const p = plans.find((x) => x.id === selected);
    const planEl = root.querySelector('[data-summary-plan]');
    if (!p || !planEl) return;
    const country = root.querySelector('[data-country]')?.value || 'Vietnam';
    planEl.textContent = `${p.label} plan`;
    root.querySelector('[data-summary-price]').textContent = `${p.price}${p.period || ''}`;
    root.querySelector('[data-summary-tax]').textContent =
      TAX_LABEL[country] || 'tax included';
  };
  const updateSelection = () => {
    plansBox.querySelectorAll('[data-plan]').forEach((el) => {
      const active = el.dataset.plan === selected;
      el.style.borderColor = active ? 'var(--c-gold)' : 'var(--c-border)';
      el.style.background = active ? 'color-mix(in srgb, var(--c-gold) 12%, transparent)' : 'var(--c-surface)';
      el.style.boxShadow = active ? '0 0 0 1px var(--c-gold)' : 'none';
      const chk = el.querySelector('[data-check]');
      if (chk) {
        chk.classList.toggle('hidden', !active);
        chk.classList.toggle('flex', active);
      }
      // CHOSEN = per-day tag đỏ nổi; DEFAULT = nền tối — mọi gói như nhau
      const pd = el.querySelector('[data-perday]');
      if (pd) pd.style.background = active ? 'var(--c-danger)' : 'var(--c-surface-2)';
    });
    updateSummary();
  };
  plansBox.addEventListener('click', (e) => {
    const card = e.target.closest('[data-plan]');
    if (!card) return;
    selected = card.dataset.plan;
    track('funnel_plan_select', { package_id: selected, screen_id: screen.id, screen_index: screen.index });
    updateSelection();
  });
  renderPlans();

  // Pricing precedence (operator 2026-07-03 — Stripe/funnel-monkey là chính):
  //   1. UA đã CHỌN Price ID trong editor → plans config có offerItemId → dùng
  //      nguyên (giá + checkout theo đúng offer item đã chọn).
  //   2. Chưa chọn → fallback: thay bằng toàn bộ offer của funnel-monkey.
  const uaPicked = plans.some((p) => p.offerItemId);
  if (!uaPicked) {
    loadRemotePlans(funnel).then((remote) => {
      if (!remote?.length || !root.isConnected) return;
      plans = normalizePlans(remote);
      selected = (plans.find((p) => p.featured) ?? plans[0]).id;
      renderPlans();
    }).catch(() => {});
  }

  // ---- checkout wiring ----
  const selectedPlan = () => plans.find((x) => x.id === selected) || plans[0];
  const pay = (provider, via) => {
    startCheckout(funnel, { provider, plan: selectedPlan(), screen })
      .then((res) => {
        if (res?.ok && res.provider !== 'monkey') {
          // monkey/Stripe embedded completes via redirect (?status=complete);
          // mock/paypal/paddle resolve in-page → advance the funnel.
          if (res.provider === 'paddle') return; // Paddle overlay: done() fires on its event
          advance({ plan: selected, via, purchased: true, provider: res.provider });
        }
      })
      .catch(() => {});
  };

  // ---- Stripe EMBEDDED INLINE (operator 2026-07-03, như funnelfox) ----
  // funnel-monkey configured → form Stripe (Link/Apple Pay/Card/currency)
  // nhúng THẲNG dưới list gói, thay mock form. Đổi gói → remount session mới.
  const payBox = root.querySelector('[data-pay]');
  let inlineHandle = null;
  let inlineToken = 0;
  const mountInline = async () => {
    const my = ++inlineToken;
    const slot = payBox.querySelector('[data-stripe-inline]');
    if (!slot) return;
    inlineHandle?.destroy();
    inlineHandle = null;
    slot.innerHTML = '<div style="text-align:center;color:#888;padding:28px 0;background:#fff;border-radius:14px">Loading secure checkout…</div>';
    try {
      const h = await mountInlineCheckout(funnel, selectedPlan(), slot, { screen });
      if (my !== inlineToken || !root.isConnected) { h.destroy(); return; }
      inlineHandle = h;
    } catch (e) {
      if (my !== inlineToken) return;
      // Stripe/checkout lỗi (hay gặp: customerEmail không hợp lệ) → yêu cầu
      // nhập lại email NGAY TẠI PAYWALL rồi GỌI LẠI Stripe — lặp đến khi
      // user nhập chuẩn và mount thành công (operator 2026-07-03).
      track('confirm_purchased_fail', {
        provider: 'card', package_id: selected, via: 'inline_mount',
        msg: String(e?.message || 'mount failed').slice(0, 100), code: e?.code || 'mount_error',
      });
      slot.innerHTML = `
        <div style="background:#fff;border-radius:14px;padding:16px;color:#1a1a1a">
          <p style="margin:0 0 4px;font-weight:700;color:#c0392b">Không mở được cổng thanh toán</p>
          <p style="margin:0 0 10px;font-size:13px;color:#555">${escapeHtml(String(e?.message || 'Checkout unavailable'))}</p>
          <p style="margin:0 0 6px;font-size:13px;color:#333">Vui lòng nhập lại email để thử lại:</p>
          <input data-retry-email type="email" placeholder="you@example.com"
            value="${escapeAttr(getState().email || '')}"
            style="width:100%;border:1px solid #ccc;border-radius:9px;padding:10px 12px;font-size:14px;margin-bottom:8px;box-sizing:border-box" />
          <p data-retry-err style="display:none;margin:0 0 8px;font-size:12px;color:#c0392b"></p>
          <button data-retry-btn type="button"
            style="width:100%;background:#111;color:#fff;border:none;border-radius:9px;padding:11px 0;font-weight:700;cursor:pointer">Thử lại thanh toán</button>
        </div>`;
      const input = slot.querySelector('[data-retry-email]');
      const errEl = slot.querySelector('[data-retry-err]');
      slot.querySelector('[data-retry-btn]').onclick = () => {
        const v = input.value.trim();
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) {
          errEl.textContent = 'Email chưa hợp lệ — kiểm tra lại giúp mình nhé.';
          errEl.style.display = 'block';
          input.focus();
          return; // LẶP đến khi nhập chuẩn
        }
        setEmail(v);
        track('funnel_insert_continue', { screen_id: 'paywall-email-retry', screen_index: screen.index, screen_type: 'engagement-insert', value: v, retry: true });
        mountInline(); // gọi lại Stripe — còn lỗi thì form này hiện lại
      };
    }
  };
  const useInline = screen.payment && payBox && hasInlineStripe(funnel);
  if (useInline) {
    payBox.innerHTML = '<div data-stripe-inline style="min-height:340px"></div>';
    mountInline();
    // đổi gói → session mới (clientSecret encode plan — per funnel-integration)
    plansBox.addEventListener('click', (e) => {
      if (e.target.closest('[data-plan]')) mountInline();
    });
    // Thanh toán bằng nút Subscribe CỦA STRIPE (operator 2026-07-03):
    // bỏ hẳn dock "GET MY VIDEO" + "Cancel anytime. Secured checkout" — nút
    // đè lên form và gây 2 CTA cạnh tranh.
    root.querySelector('.cta-dock')?.remove();
    const scroll = root.querySelector('.screen-scroll');
    if (scroll) scroll.style.paddingBottom = '24px'; // không còn dock để chừa chỗ
    // Nút Subscribe nằm TRONG iframe Stripe (cross-origin, không bắt click
    // trực tiếp). Proxy: window blur khi focus rơi vào iframe Stripe = user
    // bắt đầu thao tác thanh toán → iap_btn_click (1 lần / lần mount).
    let interacted = false;
    window.addEventListener('blur', () => {
      if (interacted || !root.isConnected) return;
      const ae = document.activeElement;
      if (ae && ae.tagName === 'IFRAME' && payBox.contains(ae)) {
        interacted = true;
        track('iap_btn_click', {
          screen_id: screen.id, screen_index: screen.index, screen_type: 'paywall',
          package_id: selected, via: 'stripe_inline',
        });
      }
    });
  }

  // payment form behavior: format card number; SUBSCRIBE + wallets open the
  // real card path (funnel-monkey embedded incl. Apple/Google Pay) or mock.
  const cardInput = root.querySelector('[data-card]');
  if (cardInput) {
    cardInput.addEventListener('input', () => {
      cardInput.value = cardInput.value.replace(/\D/g, '').slice(0, 16).replace(/(.{4})/g, '$1 ').trim();
    });
    const exp = root.querySelector('[data-exp]');
    exp.addEventListener('input', () => {
      let v = exp.value.replace(/\D/g, '').slice(0, 4);
      exp.value = v.length > 2 ? `${v.slice(0, 2)} / ${v.slice(2)}` : v;
    });
    root.querySelector('[data-subscribe]').onclick = () => pay('card', 'subscribe_form');
    root.querySelectorAll('[data-wallet]').forEach((btn) => {
      btn.onclick = () => pay('card', btn.dataset.wallet);
    });
    root.querySelector('[data-country]')?.addEventListener('change', updateSummary);
    updateSummary();

    // extra providers (config-driven): PayPal / Paddle buttons under wallets
    const extras = availableProviders(funnel).filter((p) => p.id !== 'card' && p.live);
    if (extras.length) {
      const row = document.createElement('div');
      row.className = 'flex flex-col gap-2';
      for (const p of extras) {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'w-full rounded-xl py-3.5 text-base font-semibold';
        if (p.id === 'paypal') {
          b.style.cssText = 'background:#FFC439;color:#111';
          b.innerHTML = '<i>Pay</i><i style="color:#0070BA">Pal</i>';
        } else {
          b.style.cssText = 'background:#FDDD35;color:#111';
          b.textContent = 'Paddle';
        }
        b.onclick = () => pay(p.id, p.id);
        row.appendChild(b);
      }
      const walletBlock = root.querySelector('[data-wallet]')?.parentElement;
      walletBlock?.insertBefore(row, walletBlock.querySelector('[data-card]')?.closest('div') || null);
      const divider = walletBlock?.querySelector('[data-pay-divider]');
      if (divider) walletBlock.insertBefore(row, divider);
    }
  }

  // countdown ticker — setInterval (NOT isConnected-gated recursion: the node
  // is not mounted yet when the renderer runs, which froze the timer at 15:00)
  const timerEl = root.querySelector('[data-countdown]');
  if (timerEl) {
    let remaining = (screen.countdownMin ?? 15) * 60;
    const render = () => {
      const m = String(Math.floor(remaining / 60)).padStart(2, '0');
      const s = String(remaining % 60).padStart(2, '0');
      timerEl.textContent = `${m}:${s}`;
    };
    render();
    const t = setInterval(() => {
      // stop only once it has been mounted and later removed (screen advanced)
      if (timerEl.isConnected === false && timerEl.ownerDocument.contains(timerEl) === false && remaining < (screen.countdownMin ?? 15) * 60) {
        clearInterval(t);
        return;
      }
      if (remaining <= 0) return clearInterval(t);
      remaining -= 1;
      render();
    }, 1000);
  }

  // Dock CTA: with a payment form on screen, jump to the plans/payment block
  // (funnelfox behavior); without one, it advances (legacy funnels).
  const dockCta = root.querySelector('[data-cta]');
  if (dockCta) dockCta.onclick = () => {
    if (useInline) {
      // form đã nhúng sẵn — CTA cuộn tới form (không mở modal)
      track('funnel_plan_select', { package_id: selected, via: 'dock_cta_scroll' });
      payBox.scrollIntoView({ behavior: 'smooth', block: 'start' });
    } else if (screen.payment) {
      pay('card', 'dock_cta');
    } else {
      advance({ plan: selected, via: 'dock_cta' });
    }
  };

  return root;
}

// Khu media thay rings (operator 2026-07-03 — rings nặng, bỏ hẳn):
// templatesMedia = URL ảnh hoặc video (upload từ kho creative trong editor).
function templatesMediaBlock(screen) {
  const u = screen.templatesMedia;
  if (!u) return '';
  if (/\.(mp4|webm|mov)(\?|$)/i.test(u)) {
    return `<video src="${escapeAttr(u)}" autoplay muted loop playsinline data-media
              class="max-h-[32dvh] w-full rounded-2xl object-cover shadow-lg"></video>`;
  }
  return `<img src="${escapeAttr(u)}" alt="" data-media class="max-h-[32dvh] w-full rounded-2xl object-cover shadow-lg" />`;
}

// Giá plan (Stripe/offer amount) LÀ giá FINAL đã-discount = giá TÍNH TIỀN
// (operator 2026-07-11: "giá tôi đưa là giá đã discount"). Vòng xoay KHÔNG giảm
// thêm — chỉ set strike-through `was` (giá neo CAO hơn để marketing), nên
// display = charge (hết lệch: trước đây show $5 nhưng Stripe tính $9.99).
// perDay tính từ giá final. Plan đã có `was`/oldPrice thì giữ nguyên.
// Sau discount, perDay TỰ TÍNH lại từ giá hiển thị (operator 2026-07-03).
const PERIOD_DAYS = { '/wk': 7, '/mo': 30, '/yr': 365, week: 7, month: 30, year: 365 };
// LẤY SỐ từ plan.amount (offer funnel-monkey) — KHÔNG parse chuỗi đã format
// theo locale ("9,99 US$" từng bị parse thành 999 → $142/day, bug 2026-07-03).
function planAmount(p) {
  if (typeof p.amount === 'number') return p.amount;
  const m = /^\$([\d]+(?:\.[\d]{1,2})?)$/.exec(String(p.price || '').trim());
  return m ? parseFloat(m[1]) : null;
}
function autoPerDay(p) {
  if (p.perDay) return p.perDay; // config tay vẫn thắng
  const amt = planAmount(p);
  const days = PERIOD_DAYS[p.period] || PERIOD_DAYS[p.id] || null;
  if (amt == null || !days) return undefined;
  return `$${(amt / days).toFixed(2)}`;
}
function normalizePlans(plans) {
  // Giá hiển thị = giá Stripe/offer = giá charge. KHÔNG có discount từ wheel.
  // Giữ price/was theo config (plan tự set oldPrice mới có strike-through).
  return plans.map((p) => {
    const amt = planAmount(p);
    const q = { ...p, ...(amt != null ? { amount: amt } : {}) };
    if (amt != null && !q.price) q.price = `$${amt.toFixed(2)}`;
    q.perDay = autoPerDay(q);
    return q;
  });
}

const TAX_LABEL = {
  'Vietnam': 'incl. 8% VAT',
  'United States': 'incl. sales tax',
  'United Kingdom': 'incl. 20% VAT',
  'Australia': 'incl. 10% GST',
  'Other…': 'tax included',
};

function brandBadge(label, bg, fg = '#fff') {
  return `<span class="rounded px-1.5 py-0.5 text-[10px] font-extrabold" style="background:${bg};color:${fg}">${label}</span>`;
}

function paymentForm() {
  return `
    <div class="pay-card flex flex-col gap-3" data-pay>
      <button type="button" data-wallet="apple_pay"
        class="w-full rounded-xl bg-black py-3.5 text-base font-semibold text-white"> Pay</button>
      <button type="button" data-wallet="google_pay"
        class="w-full rounded-xl border border-gray-300 bg-white py-3.5 text-base font-semibold text-gray-800">
        <span style="color:#4285F4">G</span><span style="color:#EA4335">o</span><span style="color:#FBBC05">o</span><span style="color:#4285F4">g</span><span style="color:#34A853">l</span><span style="color:#EA4335">e</span> Pay</button>
      <div class="flex items-center gap-3 text-xs text-gray-400" data-pay-divider>
        <span class="h-px flex-1 bg-gray-200"></span>or pay with card<span class="h-px flex-1 bg-gray-200"></span>
      </div>
      <div>
        <div class="pay-label">Card number</div>
        <div class="relative">
          <input class="pay-input pr-32" data-card inputmode="numeric" placeholder="1234 1234 1234 1234" />
          <span class="absolute right-2.5 top-1/2 flex -translate-y-1/2 gap-1">
            ${brandBadge('VISA', '#1A1F71')}${brandBadge('MC', '#EB001B')}${brandBadge('AMEX', '#2E77BC')}${brandBadge('JCB', '#0B4EA2')}
          </span>
        </div>
      </div>
      <div class="grid grid-cols-2 gap-3">
        <div>
          <div class="pay-label">Expiration date</div>
          <input class="pay-input" data-exp inputmode="numeric" placeholder="MM / YY" />
        </div>
        <div>
          <div class="pay-label">Security code</div>
          <input class="pay-input" inputmode="numeric" maxlength="4" placeholder="CVC" />
        </div>
      </div>
      <div>
        <div class="pay-label">Country</div>
        <select class="pay-input" data-country>
          <option selected>Vietnam</option>
          <option>United States</option>
          <option>United Kingdom</option>
          <option>Australia</option>
          <option>Other…</option>
        </select>
      </div>
      <div class="flex items-center justify-between rounded-lg bg-gray-50 px-3 py-2.5">
        <span class="text-sm font-semibold text-gray-700" data-summary-plan>—</span>
        <span class="text-right text-sm">
          <span class="font-bold text-gray-900" data-summary-price>—</span>
          <span class="block text-[11px] text-gray-500" data-summary-tax></span>
        </span>
      </div>
      <button type="button" class="pay-subscribe" data-subscribe>SUBSCRIBE</button>
      <p class="text-center text-xs text-gray-500">Your payment information is secure with SSL/TLS encryption</p>
    </div>
  `;
}

function countdownBlock(screen) {
  if (!screen.countdownMin) return '';
  return `
    <div class="shrink-0 rounded-xl px-4 py-2.5 text-center text-sm font-semibold"
         style="background: var(--c-danger); color: #fff">
      ${escapeHtml(screen.countdownText || 'Offer ends in:')} <span data-countdown class="font-mono font-bold">15:00</span>
    </div>
  `;
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
}

function escapeAttr(s) {
  return String(s).replace(/["']/g, (c) => ({ '"': '&quot;', "'": '&#39;' })[c]);
}
