import { setAnswer } from '../state.js';

// Quiz: select-then-continue (matches the live funnel — tap highlights the
// option, a separate CONTINUE confirms). CTA sits in a shrink-0 footer so it
// is always visible; the option list scrolls internally if it overflows.

export function engagementQuestion(screen, advance) {
  const root = document.createElement('section');
  root.className = 'flex h-full min-h-0 flex-1 flex-col gap-5 py-2';
  root.innerHTML = `
    ${
      screen.eyebrowImage
        ? `<img src="${escapeAttr(screen.eyebrowImage)}" alt="" class="eyebrow-img mx-auto w-auto shrink-0 object-contain" />`
        : ''
    }
    <header class="flex shrink-0 flex-col gap-2 text-center">
      ${screen.subtitle ? `<p class="t-muted t-body">${escapeHtml(screen.subtitle)}</p>` : ''}
      <h1 class="t-title t-screen-title font-bold">
        ${escapeHtml(screen.question || 'Tell us about you')}
      </h1>
    </header>
    <div class="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto" data-options data-stagger></div>
    <div class="shrink-0 pt-1">
      <button type="button" class="btn-primary" data-cta disabled>${escapeHtml(screen.cta || 'Continue')}</button>
    </div>
  `;
  const box = root.querySelector('[data-options]');
  const ctaBtn = root.querySelector('[data-cta]');
  const options = screen.options || ['Option A', 'Option B'];
  // default pre-selected option so the flow is never blocked (operator rule)
  const defaultIdx = Number.isInteger(screen.defaultOption) ? screen.defaultOption : 0;
  let selected = null;

  options.forEach((opt, i) => {
    const label = typeof opt === 'string' ? opt : opt.label;
    const value = typeof opt === 'string' ? opt : (opt.value ?? opt.label);
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'btn-option shrink-0';
    btn.textContent = label;
    btn.onclick = () => {
      selected = value;
      box.querySelectorAll('.btn-option').forEach((b) => b.classList.toggle('selected', b === btn));
      ctaBtn.disabled = false;
    };
    box.appendChild(btn);
    if (i === defaultIdx) {
      selected = value;
      btn.classList.add('selected');
      ctaBtn.disabled = false;
    }
  });

  ctaBtn.onclick = () => {
    if (selected == null) return;
    setAnswer(screen.id, selected);
    advance({ choice: selected });
  };
  return root;
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
}

function escapeAttr(s) {
  return String(s).replace(/["']/g, (c) => ({ '"': '&quot;', "'": '&#39;' })[c]);
}
