// Vendor pixels — Facebook (Meta) Pixel, config-driven theo ĐÚNG dialect
// funnelfox liveops (soi từ app.artimind.com/wc_mascot_us 2026-07-03):
//
//   funnel.vendor = {
//     metaPixel: {
//       id: "1492068642251123",
//       includeValue: true,            // gắn value+currency vào Purchase
//       events: {                       // purchase lifecycle → tên event FB
//         subscription_start: { browser: true, event_name: "Purchase" },
//         trial_start:        { browser: true, event_name: "StartTrial" },
//         one_off:            { browser: true, event_name: "Purchase" }
//       }
//     },
//     tiktokPixel: { id: "..." },       // stub — chưa implement
//     google: { measurementId: "G-…" }  // stub — Firebase/gtag đã có đường riêng
//   }
//
// Mapping event nội bộ → FB standard events:
//   funnel_start            → PageView (fbq init tự bắn)
//   iap_view                → ViewContent {content_name: funnel_id}
//   funnel_insert_continue  → Lead (chỉ màn email, có value, không skip)
//   iap_checkout_open       → InitiateCheckout
//   iap_successfull         → events.subscription_start.event_name (default Purchase)
//                             + {value, currency} khi includeValue
//
// fbclid → _fbp/_fbc cookie: fbevents.js tự xử lý, không cần code thêm.
// Server-side (CAPI, cờ `server:true`) là việc BE — module này chỉ browser.

let fb = null; // { id, includeValue, events }

export function initVendors(funnel, { muted } = {}) {
  const mp = funnel?.vendor?.metaPixel;
  if (!mp?.id || muted) return; // editor/preview không bắn pixel
  fb = { id: String(mp.id), includeValue: mp.includeValue !== false, firstPurchaseOnly: !!mp.firstPurchaseOnly, events: mp.events || {}, _purchased: false };
  // stub fbq chuẩn của Meta — script load async, event queue trước đó vẫn giữ
  /* eslint-disable */
  !(function (f, b, e, v, n, t, s) {
    if (f.fbq) return;
    n = f.fbq = function () { n.callMethod ? n.callMethod.apply(n, arguments) : n.queue.push(arguments); };
    if (!f._fbq) f._fbq = n;
    n.push = n; n.loaded = !0; n.version = '2.0'; n.queue = [];
    t = b.createElement(e); t.async = !0; t.src = v;
    s = b.getElementsByTagName(e)[0]; s.parentNode.insertBefore(t, s);
  })(window, document, 'script', 'https://connect.facebook.net/en_US/fbevents.js');
  /* eslint-enable */
  window.fbq('init', fb.id);
  window.fbq('track', 'PageView');
}

function fbTrack(name, params, custom = false) {
  try {
    if (!fb || !window.fbq) return;
    window.fbq(custom ? 'trackCustom' : 'track', name, params || {});
  } catch { /* pixel must never break the funnel */ }
}

// parse "$9.99" → 9.99 (USD); price đã format từ funnel-monkey offer
function planValue(p) {
  const m = /([\d.,]+)/.exec(String(p?.price || ''));
  return m ? parseFloat(m[1].replace(',', '')) : undefined;
}

// Hook từ tracking.track() — nhận MỌI event nội bộ, map sang pixel.
// Mapping THEO SPEC OPERATOR 2026-07-03 (sửa lần 2):
//   nhìn thấy 1 màn (*_view)            → screen_complete (custom)
//   thấy màn THỨ 2 (index 1, lần đầu)   → second_screen_presented (custom)
//   điền email + continue thành công    → CompleteRegistration (standard)
//   bấm CTA thường (KHÔNG paywall /     → button_click (custom)
//     KHÔNG màn download-app /
//     KHÔNG màn chọn câu hỏi)
//   mở checkout                          → InitiateCheckout · pay xong → Purchase
let secondScreenFired = false;
export function vendorHook(name, ev) {
  if (!fb) return;
  const isView = name === 'iap_view' || (name.startsWith('funnel_') && name.endsWith('_view'));
  if (isView) {
    fbTrack('screen_complete', { screen_id: ev.screen_id, screen_index: ev.screen_index, funnel_id: ev.funnel_id }, true);
    if (ev.screen_index === 1 && !secondScreenFired) {
      secondScreenFired = true;
      fbTrack('second_screen_presented', { funnel_id: ev.funnel_id }, true);
    }
    return;
  }
  if (name === 'funnel_insert_continue' && ev.value && !ev.skipped && /@/.test(String(ev.value))) {
    fbTrack('CompleteRegistration', { content_name: ev.funnel_id });
    return;
  }
  // CTA thường: continue của mọi màn TRỪ paywall (iap_btn_click),
  // successfull (nút download app) và engagement-question (màn chọn câu hỏi)
  const isCont = name.startsWith('funnel_') && (name.endsWith('_continue') || name.endsWith('_done'));
  if (isCont && name !== 'funnel_question_continue' && name !== 'funnel_successfull_continue') {
    fbTrack('button_click', { screen_id: ev.screen_id, screen_index: ev.screen_index, funnel_id: ev.funnel_id }, true);
    return;
  }
  if (name === 'iap_checkout_open') {
    fbTrack('InitiateCheckout', { content_name: ev.funnel_id, content_ids: [ev.package_id].filter(Boolean) });
  } else if (name === 'iap_successfull') {
    const cfg = fb.events.subscription_start || {};
    if (cfg.enabled === false || cfg.browser === false) return;
    if (fb.firstPurchaseOnly && fb._purchased) return; // funnelfox option
    fb._purchased = true;
    const params = { content_name: ev.funnel_id, content_ids: [ev.purchase_package_id].filter(Boolean) };
    if (fb.includeValue && ev.value != null) { params.value = ev.value; params.currency = ev.currency || 'USD'; }
    fbTrack(cfg.event_name || 'Purchase', params);
  }
}

export { planValue };
