// Lucky wheel — gamified discount before the paywall.
// Ported from operator-provided Lucky Wheel HTML (message (1).txt, 2026-06-12).
// Playbook (funnel-review/screens/wheel.md): one clear action, Continue appears
// only AFTER the spin, and the won discount must carry into the paywall price.

import { setAnswer, setDiscount } from '../state.js';

const PRIZES = [
  { label: '10%', value: 10, color: '#F8545D', winner: false },
  { label: '50%', value: 50, color: '#FFC73B', winner: true },
  { label: 'x',   value: 0,  color: '#7E0612', winner: false },
  { label: '20%', value: 20, color: '#F8545D', winner: false },
  { label: '5%',  value: 5,  color: '#7E0612', winner: false },
  { label: 'TRY', value: 0,  color: '#FFC73B', winner: false },
];
const SLICE = 360 / PRIZES.length;
const SPIN_MS = 6800;
const TEASE_AT_MS = 4600;

export function wheel(screen, advance) {
  const root = document.createElement('section');
  root.className = 'wheel-screen flex h-full min-h-0 flex-1 cursor-pointer flex-col items-center justify-center gap-3 py-2 text-center';
  root.innerHTML = `
    ${
      screen.eyebrowImage
        ? `<img src="${escapeAttr(screen.eyebrowImage)}" alt="" class="eyebrow-img mx-auto w-auto shrink-0 object-contain" />`
        : ''
    }
    <p class="t-muted t-body max-w-[320px] leading-relaxed">
      ${escapeHtml(screen.subtitle || "You've been chosen to spin our lucky wheel. Try your luck and claim your exclusive discount — only one spin per user.")}
    </p>

    <div class="wheel-box ready" data-wheel-box role="button" aria-label="Spin the lucky wheel" tabindex="0">
      <div class="wheel-pointer"></div>
      <div class="glow-ring"></div>
      <svg class="wheel" data-wheel viewBox="0 0 300 300"></svg>
    </div>
    <span class="wheel-sparkle"></span>
    <span class="wheel-sparkle"></span>
    <span class="wheel-sparkle"></span>
    <span class="wheel-sparkle"></span>

    <p class="wheel-tease" data-tease>Almost there...</p>
    <p class="tap-hint" data-tap-hint>Tap anywhere to spin</p>

    <div class="wheel-reveal" data-reveal>
      <p class="eyebrow">Success</p>
      <p class="amount" data-reveal-amount>50% OFF</p>
      <p class="note">Applied at checkout — limited to this session only.</p>
    </div>

    <div class="mt-2 hidden w-full max-w-[320px]" data-continue-wrap>
      <button type="button" class="btn-primary" data-continue>${escapeHtml(screen.cta || 'Claim my discount')}</button>
    </div>

    <div class="confetti" data-confetti></div>
  `;

  const wheelEl = root.querySelector('[data-wheel]');
  const wheelBox = root.querySelector('[data-wheel-box]');
  const tapHint = root.querySelector('[data-tap-hint]');
  const tease = root.querySelector('[data-tease]');
  const reveal = root.querySelector('[data-reveal]');
  const revealAmount = root.querySelector('[data-reveal-amount]');
  const confetti = root.querySelector('[data-confetti]');
  const continueWrap = root.querySelector('[data-continue-wrap]');

  // Build the SVG wheel
  const cx = 150, cy = 150, r = 140;
  let svgInner = '';
  PRIZES.forEach((p, i) => {
    const start = i * SLICE;
    const end = start + SLICE;
    const a1 = (start - 90) * Math.PI / 180;
    const a2 = (end - 90) * Math.PI / 180;
    const x1 = cx + r * Math.cos(a1), y1 = cy + r * Math.sin(a1);
    const x2 = cx + r * Math.cos(a2), y2 = cy + r * Math.sin(a2);
    const mid = ((start + end) / 2 - 90) * Math.PI / 180;
    const tx = cx + r * 0.6 * Math.cos(mid);
    const ty = cy + r * 0.6 * Math.sin(mid);

    svgInner += `
      <path
        d="M ${cx} ${cy} L ${x1} ${y1} A ${r} ${r} 0 0 1 ${x2} ${y2} Z"
        fill="${p.color}" stroke="rgba(0,0,0,0.25)" stroke-width="1"
      />
      <text
        x="${tx}" y="${ty}"
        fill="#fff"
        font-size="${p.winner ? 22 : 16}"
        font-weight="${p.winner ? 800 : 700}"
        text-anchor="middle"
        dominant-baseline="middle"
        transform="rotate(${start + SLICE / 2} ${tx} ${ty})"
        style="text-shadow: 0 1px 2px rgba(0,0,0,0.6)"
      >${p.label}</text>
    `;
  });
  svgInner += `
    <circle cx="${cx}" cy="${cy}" r="28" fill="#fff" />
    <circle cx="${cx}" cy="${cy}" r="10" fill="#42050A" />
  `;
  wheelEl.innerHTML = svgInner;

  let spun = false;
  let spinning = false;

  function createClickRipple(x, y) {
    const ripple = document.createElement('span');
    ripple.className = 'click-ripple';
    ripple.style.setProperty('--x', `${x}px`);
    ripple.style.setProperty('--y', `${y}px`);
    document.body.appendChild(ripple);
    ripple.addEventListener('animationend', () => ripple.remove(), { once: true });
  }

  function spinWheel(event) {
    if (spun || spinning) return;
    spun = true;
    spinning = true;
    root.classList.remove('cursor-pointer');
    root.classList.add('spinning');
    wheelBox.classList.remove('ready');
    tapHint.classList.add('hide');
    if (typeof event?.clientX === 'number' && typeof event?.clientY === 'number') {
      createClickRipple(event.clientX, event.clientY);
    }

    const winnerIndex = PRIZES.findIndex((p) => p.winner);
    const boundaryAfterWinner = (winnerIndex + 1) * SLICE;
    const almostLostOffset = 0.8;
    const finalTarget = -(360 * 9 + boundaryAfterWinner - almostLostOffset);

    wheelBox.classList.add('spinning');
    wheelEl.style.transform = 'rotate(0deg)';
    wheelEl.style.transition = 'none';
    void wheelEl.offsetWidth;

    const spinAnimation = wheelEl.animate(
      [
        { transform: 'rotate(0deg)', easing: 'cubic-bezier(0.08, 0.76, 0.02, 1)' },
        { transform: `rotate(${finalTarget}deg)` },
      ],
      { duration: SPIN_MS, fill: 'forwards' },
    );

    const teaseTimer = setTimeout(() => {
      tease.classList.add('show');
    }, TEASE_AT_MS);

    spinAnimation.onfinish = () => {
      clearTimeout(teaseTimer);
      wheelEl.style.transform = `rotate(${finalTarget}deg)`;
      spinAnimation.cancel();
      wheelBox.classList.remove('spinning');
      wheelBox.classList.add('done');
      root.classList.remove('spinning');
      root.classList.add('done');
      tease.classList.remove('show');
      spinning = false;

      const winner = PRIZES[winnerIndex];
      revealAmount.textContent = `${winner.label} OFF`;
      reveal.classList.add('show');

      setAnswer(screen.id, winner.value);
      setDiscount(winner.value);

      // Continue appears only after the spin (wheel.md: never show both exits)
      continueWrap.classList.remove('hidden');

      confetti.innerHTML = '';
      const colors = ['#FFC73B', '#F8545D', '#FFFFFF', '#FF8A1E', '#22C55E'];
      for (let i = 0; i < 30; i++) {
        const piece = document.createElement('span');
        piece.className = 'piece';
        piece.style.left = `${(i * 3.4 + (i % 5) * 1.5) % 100}%`;
        piece.style.background = colors[i % colors.length];
        piece.style.setProperty('--delay', `${(i % 8) * 120}ms`);
        piece.style.setProperty('--dur', `${1800 + ((i * 137) % 900)}ms`);
        piece.style.setProperty('--rot', `${(i * 47) % 360}deg`);
        confetti.appendChild(piece);
      }
      confetti.classList.add('show');
      setTimeout(() => confetti.classList.remove('show'), 4000);
    };
  }

  root.addEventListener('pointerdown', (event) => {
    if (event.target.closest('[data-continue]')) return;
    spinWheel(event);
  });
  root.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      spinWheel();
    }
  });
  root.querySelector('[data-continue]').onclick = () => {
    const won = PRIZES.find((p) => p.winner);
    advance({ discount: won.value });
  };

  return root;
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
}

function escapeAttr(s) {
  return String(s).replace(/["']/g, (c) => ({ '"': '&quot;', "'": '&#39;' })[c]);
}
