// funnel-monkey adapter — Apero's in-house FunnelFox-clone payment platform
// (https://funnel-monkey.aperogroup.ai). Client contract (same one the BE team
// wired into Genius Web, VSL-Web-IIP055-Genius):
//
//   headers: x-publishable-key: <PROJECT pk_…>   (NOT the Stripe key)
//   GET  {apiBase}/funnel/offer/{projectSlug}/{funnelSlug}
//        → { data: { stripePublishableKey, items: [{ id, displayName,
//            sortOrder, price: { currency, unitAmount, interval },
//            product: { name } }] } }
//   POST {apiBase}/funnel/checkout
//        body { offerItemId, uiMode: 'embedded', returnUrl, customerEmail? }
//        → { data: { clientSecret } }   → Stripe embedded checkout mount
//
// FunnelFox feature parity carried by this path: dynamic plan list from the
// offer, embedded card form (user never leaves the page), Apple Pay/Google Pay
// (Stripe embedded checkout renders express wallets automatically), discount
// display carried from the wheel, session attribution via returnUrl params.
// The Stripe SECRET never touches the browser.

import { openModal, modalBody, onModalCleanup } from './modal.js';

const ZERO_DECIMAL = new Set(['jpy', 'krw', 'vnd', 'clp', 'huf']);

export function isConfigured(cfg) {
  return !!(cfg && cfg.apiBase && cfg.publishableKey && cfg.projectSlug && cfg.funnelSlug);
}

function headers(cfg) {
  return { 'Content-Type': 'application/json', 'x-publishable-key': cfg.publishableKey };
}

function formatPrice(p) {
  if (!p) return '';
  const cur = (p.currency || 'usd').toLowerCase();
  const amt = ZERO_DECIMAL.has(cur) ? p.unitAmount : p.unitAmount / 100;
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: cur.toUpperCase() }).format(amt);
  } catch {
    return `${amt} ${cur.toUpperCase()}`;
  }
}

function interval(p) {
  return p?.interval ? String(p.interval).toLowerCase() : 'month';
}

let offerPromise = null;

// Fetch the funnel's mapped offer (version-less). Cached for the session.
export function loadOffer(cfg) {
  if (!isConfigured(cfg)) return Promise.resolve(null);
  if (offerPromise) return offerPromise;
  const url = `${cfg.apiBase}/funnel/offer/${cfg.projectSlug}/${cfg.funnelSlug}`;
  offerPromise = fetch(url, { headers: headers(cfg) })
    .then(async (r) => {
      const b = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(b.message || `HTTP ${r.status}`);
      return b.data || null;
    })
    .catch((e) => {
      console.warn('[monkey] loadOffer failed:', e?.message);
      offerPromise = null;
      return null;
    });
  return offerPromise;
}

// Map the offer → paywall plan shape ({ id, label, price, period, featured }).
// Each plan carries offerItemId for checkout. Returns null when unavailable
// → the paywall falls back to its local config plans.
export async function getOfferPlans(cfg) {
  const offer = await loadOffer(cfg);
  if (!offer || !Array.isArray(offer.items) || !offer.items.length) return null;
  const items = offer.items.slice().sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0));
  const plans = items.map((it) => {
    const per = interval(it.price);
    const period = /week/.test(per) ? '/wk' : /year/.test(per) ? '/yr' : /day/.test(per) ? '/day' : '/mo';
    const cur = (it.price?.currency || 'usd').toLowerCase();
    return {
      id: it.id,
      label: it.displayName || it.product?.name || 'Plan',
      price: formatPrice(it.price),
      // amount SỐ (không parse từ chuỗi format — locale phẩy/chấm gây sai giá)
      amount: ZERO_DECIMAL.has(cur) ? it.price?.unitAmount : (it.price?.unitAmount ?? 0) / 100,
      currency: cur.toUpperCase(),
      period,
      offerItemId: it.id,
    };
  });
  if (!plans.length) return null;
  const f = plans.find((p) => p.period === '/wk') || plans[0];
  f.featured = true;
  f.badge = '🔥 MOST POPULAR';
  return plans;
}

// Resolve a local plan id (week/month/year) → offer item id by interval.
export async function offerItemIdForPlan(cfg, planId) {
  const offer = await loadOffer(cfg);
  if (!offer || !Array.isArray(offer.items)) return null;
  const want = { week: 'week', month: 'month', year: 'year' }[planId];
  const byInterval = want && offer.items.find((it) => interval(it.price).indexOf(want) === 0);
  return (byInterval || offer.items.find((it) => it.id === planId) || null)?.id || null;
}

let stripeJsPromise = null;
function loadStripeJs() {
  if (window.Stripe) return Promise.resolve();
  if (stripeJsPromise) return stripeJsPromise;
  stripeJsPromise = new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = 'https://js.stripe.com/v3/';
    s.onload = resolve;
    s.onerror = () => reject(new Error('Stripe.js failed to load'));
    document.head.appendChild(s);
  });
  return stripeJsPromise;
}

// Mount Stripe's EMBEDDED checkout INLINE vào 1 element trên paywall
// (operator 2026-07-03 — form nằm ngay dưới list gói như funnelfox, không
// modal). Mỗi plan = 1 checkout session; đổi gói → destroy + mount lại.
export async function mountInline(cfg, plan, mountEl, { sessionId, customerEmail, onComplete } = {}) {
  await loadStripeJs();
  const offer = await loadOffer(cfg);
  const pk = offer?.stripePublishableKey;
  if (!pk) throw new Error('Stripe key unavailable for this offer');
  const offerItemId = plan?.offerItemId || (await offerItemIdForPlan(cfg, plan?.id));
  if (!offerItemId) throw new Error('No matching plan in the offer');
  const returnUrl =
    `${location.origin}${location.pathname}` +
    `?funnel=${encodeURIComponent(new URLSearchParams(location.search).get('funnel') || '')}` +
    `&status=complete&plan=${encodeURIComponent(plan?.id || '')}&sid=${encodeURIComponent(sessionId || '')}` +
    `&session_id={CHECKOUT_SESSION_ID}`;
  const r = await fetch(`${cfg.apiBase}/funnel/checkout`, {
    method: 'POST',
    headers: headers(cfg),
    // customerEmail → Stripe điền sẵn ô email (lấy từ màn nhập email của funnel)
    body: JSON.stringify({ offerItemId, uiMode: 'embedded', returnUrl, ...(customerEmail ? { customerEmail } : {}) }),
  });
  const b = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(b.message || `HTTP ${r.status}`);
  const clientSecret = b.data?.clientSecret;
  if (!clientSecret) throw new Error('No clientSecret returned');
  const stripe = window.Stripe(pk);
  const embedded = await stripe.initEmbeddedCheckout({
    clientSecret,
    // fires khi Stripe xác nhận thanh toán XONG, trước khi redirect returnUrl
    // — chỗ duy nhất bắt được "user bấm Subscribe trong iframe và pay thành công"
    onComplete: () => { try { onComplete?.(); } catch { /* noop */ } },
  });
  mountEl.innerHTML = '';
  embedded.mount(mountEl);
  return { destroy: () => { try { embedded.destroy(); } catch { /* noop */ } } };
}

// Mount Stripe's EMBEDDED checkout for one plan in the shared modal.
// On completion Stripe redirects to returnUrl (?status=complete) — handled on
// boot by payments/index.js handleCheckoutReturn.
export async function checkout(cfg, plan, { fail, sessionId, customerEmail }) {
  openModal(`Complete your purchase — ${plan?.label || 'plan'}`);
  const mount = modalBody();
  try {
    await loadStripeJs();
    const offer = await loadOffer(cfg);
    const pk = offer?.stripePublishableKey;
    if (!pk) throw new Error('Stripe key unavailable for this offer');
    const offerItemId = plan?.offerItemId || (await offerItemIdForPlan(cfg, plan?.id));
    if (!offerItemId) throw new Error('No matching plan in the offer');
    const returnUrl =
      `${location.origin}${location.pathname}` +
      `?funnel=${encodeURIComponent(new URLSearchParams(location.search).get('funnel') || '')}` +
      `&status=complete&plan=${encodeURIComponent(plan?.id || '')}&sid=${encodeURIComponent(sessionId || '')}` +
      `&session_id={CHECKOUT_SESSION_ID}`;
    const r = await fetch(`${cfg.apiBase}/funnel/checkout`, {
      method: 'POST',
      headers: headers(cfg),
      body: JSON.stringify({ offerItemId, uiMode: 'embedded', returnUrl, ...(customerEmail ? { customerEmail } : {}) }),
    });
    const b = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(b.message || `HTTP ${r.status}`);
    const clientSecret = b.data?.clientSecret;
    if (!clientSecret) throw new Error('No clientSecret returned');
    const stripe = window.Stripe(pk);
    const embedded = await stripe.initEmbeddedCheckout({ clientSecret });
    onModalCleanup(() => { try { embedded.destroy(); } catch { /* noop */ } });
    if (!document.getElementById('checkout-modal')) { try { embedded.destroy(); } catch { /* noop */ } return { ok: false }; }
    mount.innerHTML = '';
    embedded.mount(mount);
    return { ok: true, provider: 'monkey' };
  } catch (e) {
    if (mount) mount.innerHTML = `<p style="color:#c0392b;margin:0;text-align:center;padding:24px 0">${String(e?.message || 'Checkout failed.')}</p>`;
    fail?.(e);
    return { ok: false, error: e };
  }
}
