// Funnel registry — CONCEPT → STYLE → FUNNEL model (MKT workflow 2026-07-03).
//
//   src/config/templates/*.json  — templates = CONCEPTS, owned by the MKT
//                                  manager (Huy). { id, concept, screens, ... }
//   src/config/funnels/*.json    — funnel INSTANCES (biến thể). Two shapes:
//     a) standalone (legacy): { id, title, theme, screens: [...] }
//     b) clone: { id, template: "<template-id>", style: "<style-id>",
//                 owner: "<mkter>", overrides: {...} }
//        overrides = { title?, theme?, payment?, screens: [{ id, ...patch }] }
//        merged over the template by screen id (same rule as RC nested shape).
//
// Dimension hierarchy for reporting (whiteboard 2026-07-03):
//   Concept (template.concept) → Style (instance.style) → Funnel (instance.id)
//   with owner = MKTer filter.
//
// Select with ?funnel=<id>; default = reunion.
//
// Remote layer (unchanged): Firebase Remote Config param `funnel_<id>` (JSON)
// merged over the resolved config. TWO accepted shapes:
//
// 1. FLAT (operator spec 2026-06-12) — positional keys, scrN = screen N:
//    { "funnel_name": "reunion",
//      "scr1_type": "showcase", "scr1_logo": "<url>", "scr1_reward": "<url>",
//      "scr1_title": "...", "scr1_content": "<img-or-mp4-url>",
//      "scr1_btn_text": "Continue", "scr1_btn_color": "#fff",
//      "scr1_btn_animation": "pulse", ... }
//
// 2. NESTED (suggested) — same fields grouped per screen, matched by id.
//
// Fallback rule (operator): empty value or failed load → component hidden or
// default — enforced by the renderers, so a half-filled config never breaks.
//
// Local secrets: public/payment.local.json (gitignored) is fetched at boot and
// deep-merged into funnel.payment — keys/planIds stay out of committed JSON.

import { getRemoteFunnelOverride } from '../firebase.js';
import PRODUCTS from './products.json';

const templateModules = import.meta.glob('./templates/*.json', { eager: true });
const funnelModules = import.meta.glob('./funnels/*.json', { eager: true });

export const TEMPLATES = {};
for (const mod of Object.values(templateModules)) {
  const t = mod.default;
  if (t?.id) TEMPLATES[t.id] = t;
}

export const FUNNELS = {};
for (const mod of Object.values(funnelModules)) {
  const f = mod.default;
  if (f?.id) FUNNELS[f.id] = f;
}

// flat-key field → screen-config field
const FLAT_FIELD_MAP = {
  type: 'type',
  logo: 'logoImage',
  reward: 'awardImage',
  award: 'awardImage',
  title: 'title',
  subtitle: 'subtitle',
  content: '__media__',
  media: '__media__',
  btn_text: 'btnText',
  btn_color: 'btnColor',
  btn_text_color: 'btnTextColor',
  btn_animation: 'btnAnimation',
  cta: 'btnText',
  // input / question fields
  question: 'question',
  placeholder: 'placeholder',
  helper: 'helper',
  note: 'note',
  // validation copy — remote-configurable, the in-code strings are defaults
  // (operator 2026-06-15: error UX writing must be tunable from Firebase)
  error_empty: 'emptyError',
  error_invalid: 'invalidError',
};

export function deepMerge(base, patch) {
  if (patch == null) return base;
  if (Array.isArray(base) || Array.isArray(patch) || typeof base !== 'object' || typeof patch !== 'object' || base == null) {
    return patch;
  }
  const out = { ...base };
  for (const [k, v] of Object.entries(patch)) out[k] = deepMerge(base?.[k], v);
  return out;
}

// Resolve a funnel instance: standalone → as-is; clone → template + overrides.
export function instantiate(def) {
  if (!def) return null;
  if (!def.template) {
    const product = PRODUCTS[def.product || 'artimind'];
    const productVendor = product?.metaPixel ? { metaPixel: product.metaPixel } : null;
    return {
      ...def,
      vendor: deepMerge(productVendor, def.vendor),
      siteName: def.webName || product?.siteName || null,
      favicon: def.favicon || product?.favicon || null,
      funnelId: def.id, conceptId: def.concept || null, styleId: def.style || null, templateId: null,
    };
  }
  const tpl = TEMPLATES[def.template];
  if (!tpl) {
    console.warn(`[funnel] template "${def.template}" not found for funnel "${def.id}"`);
    return null;
  }
  let merged = {
    ...tpl,
    id: def.id,
    kind: undefined,
    owner: def.owner || tpl.owner,
    style: def.style || null,
    screens: [...tpl.screens],
  };
  const ov = def.overrides || {};
  if (ov.title) merged.title = ov.title;
  if (ov.theme) merged.theme = ov.theme;
  merged = mergeFunnel(merged, { screens: ov.screens });
  // payment/tracking: template defaults ← overrides.payment ← def.payment
  merged.payment = deepMerge(deepMerge(tpl.payment, ov.payment), def.payment);
  merged.tracking = deepMerge(deepMerge(tpl.tracking, ov.tracking), def.tracking);
  // vendor (FB pixel…): PRODUCT integrations là nền ("changes apply to all
  // funnels" như funnelfox) ← template ← overrides ← funnel def.
  const product = PRODUCTS[def.product || tpl.product || 'artimind'];
  const productVendor = product?.metaPixel ? { metaPixel: product.metaPixel } : null;
  merged.product = def.product || tpl.product || 'artimind';
  merged.vendor = deepMerge(deepMerge(deepMerge(productVendor, tpl.vendor), ov.vendor), def.vendor);
  merged.siteName = def.webName || ov.webName || tpl.webName || product?.siteName || null;
  merged.favicon = def.favicon || tpl.favicon || product?.favicon || null;
  merged.funnelId = def.id;
  merged.templateId = tpl.id;
  merged.conceptId = tpl.concept || tpl.id;
  merged.styleId = def.style || null;
  return merged;
}

// Default funnel: ?funnel= wins; else the id baked at build time
// (VITE_DEFAULT_FUNNEL — deploy_monkey.py bakes one funnel per CDN bundle);
// else reunion.
const BAKED_DEFAULT = import.meta.env.VITE_DEFAULT_FUNNEL || 'reunion';

function getLocalFunnel() {
  const id = new URLSearchParams(location.search).get('funnel');
  // ?funnel=tpl:<template-id> — preview a TEMPLATE directly (template builder)
  if (id?.startsWith('tpl:') && TEMPLATES[id.slice(4)]) {
    return instantiate({ ...TEMPLATES[id.slice(4)], template: undefined });
  }
  const def = FUNNELS[id] || FUNNELS[BAKED_DEFAULT] || FUNNELS.reunion;
  return instantiate(def) || instantiate(FUNNELS.reunion);
}

// Adapter for the MOBILE APP's existing onboarding remote-config convention
// (Confluence IIP032.2.3.1B ONB — showcase_flow*_scenario_* + onboarding_new_config):
// snake_case app fields → web funnel screen fields. Lets MKT reuse the exact
// same JSON dialect they already write for the iOS onboarding.
function adaptAppScreen(s) {
  if (!s || typeof s !== 'object') return s;
  const out = { ...s };
  const type = s.screen_type || s.type;
  if (type === 'question') out.type = 'engagement-question';
  if (type === 'showcase') out.type = 'showcase';
  if (s.video_url) out.video = s.video_url;
  if (s.video_first_frame) out.poster = s.video_first_frame;
  if (s.image_url) out.image = s.image_url;
  if (!out.image && s.ani_image_url) out.image = s.ani_image_url;
  if (s.title_color) out.titleColor = s.title_color;
  if (s.subtitle_color) out.subtitleColor = s.subtitle_color;
  if (s.button_cta) out.btnText = s.button_cta;
  if (s.button_cta_background_color) out.btnColor = s.button_cta_background_color;
  if (s.button_cta_text_color) out.btnTextColor = s.button_cta_text_color;
  // validation copy aliases (app-style snake_case → web fields)
  if (s.error_empty || s.empty_error) out.emptyError = s.error_empty || s.empty_error;
  if (s.error_invalid || s.invalid_error) out.invalidError = s.error_invalid || s.invalid_error;
  // question dialect: questions[0] drives the screen (web = 1 question/screen)
  const q = Array.isArray(s.questions) ? s.questions[0] : null;
  if (q) {
    out.type = out.type || 'engagement-question';
    if (q.question_text) out.question = q.question_text;
    if (Array.isArray(q.answers)) out.options = q.answers.map((a) => a.answer_text ?? a);
    if (Array.isArray(q.default_answer) && out.options) {
      const i = out.options.indexOf(q.default_answer[0]);
      if (i >= 0) out.defaultOption = i;
    }
  }
  for (const k of ['screen_type', 'video_url', 'video_first_frame', 'image_url', 'ani_image_url', 'title_color',
    'subtitle_color', 'button_cta', 'button_cta_background_color', 'button_cta_text_color', 'questions']) {
    delete out[k];
  }
  return out;
}

function normalizeOverride(raw) {
  if (!raw) return null;
  const flatKeys = Object.keys(raw).filter((k) => /^scr\d+_/.test(k));
  if (!flatKeys.length) {
    // nested (suggested) or app-convention { screens: [...] }
    if (Array.isArray(raw.screens)) {
      return { ...raw, screens: raw.screens.map(adaptAppScreen) };
    }
    return raw;
  }
  const byIndex = {};
  for (const k of flatKeys) {
    const m = k.match(/^scr(\d+)_(.+)$/);
    const idx = Number(m[1]);
    const field = FLAT_FIELD_MAP[m[2]] || m[2];
    byIndex[idx] ??= {};
    if (field === '__media__') {
      if (/\.(mp4|webm|mov)(\?|$)/i.test(raw[k])) byIndex[idx].video = raw[k];
      else byIndex[idx].image = raw[k];
    } else {
      byIndex[idx][field] = raw[k];
    }
  }
  for (const i of Object.keys(byIndex)) byIndex[i] = adaptAppScreen(byIndex[i]);
  return { title: raw.funnel_name, screensByIndex: byIndex };
}

export function mergeFunnel(local, rawOverride) {
  const override = normalizeOverride(rawOverride);
  if (!override) return local;
  const merged = { ...local, screens: [...local.screens] };
  if (override.title) merged.title = override.title;
  if (override.theme) merged.theme = override.theme;
  // flat positional merge: scrN ↔ screens[N-1]
  if (override.screensByIndex) {
    for (const [idx, patch] of Object.entries(override.screensByIndex)) {
      const i = Number(idx) - 1;
      if (merged.screens[i]) merged.screens[i] = { ...merged.screens[i], ...patch };
      else merged.screens.push({ id: `scr${idx}`, ...patch });
    }
    return merged;
  }
  // nested merge by screen id
  if (Array.isArray(override.screens)) {
    for (const os of override.screens) {
      if (!os || typeof os !== 'object') continue;
      const i = merged.screens.findIndex((s) => s.id === os.id);
      if (i >= 0) merged.screens[i] = { ...merged.screens[i], ...os };
      else merged.screens.push(os);
    }
  }
  return merged;
}

// public/payment.local.json — machine-local provider keys (gitignored).
// Shape: { "*": {...}, "<funnel-id>": {...} } — funnel-specific wins over "*".
async function getLocalPaymentOverride(funnelId) {
  // dev-only: file secret máy-local, không bao giờ ship lên CDN — prod fetch
  // sẽ 403 vô ích (funnel-monkey static host) nên bỏ qua hẳn.
  if (import.meta.env.PROD) return null;
  try {
    const r = await fetch('/payment.local.json', { cache: 'no-store' });
    if (!r.ok) return null;
    const all = await r.json();
    return deepMerge(all['*'], all[funnelId]) ?? null;
  } catch {
    return null;
  }
}

// Hậu tố URL (operator 2026-07-03) — nhận cả path segment, hash lẫn query:
//   …/hiepnv-test  → môi trường TEST: offer funnel-monkey chuyển sang slug
//                    "<funnelSlug>-test" (map offer TEST trên dashboard),
//                    pixel tắt, event gắn env=test.
//   …/purchase     → nhảy thẳng màn thanh toán (paywall) dù đang ở màn nào.
export function urlModes() {
  const hay = `${location.pathname} ${location.hash} ${location.search}`;
  return {
    test: /\/hiepnv-test(\/|\b)/.test(hay) || /[?&#]hiepnv-test\b/.test(hay),
    purchase: /\/purchase(\/|\b)/.test(hay) || /[?&#]purchase\b/.test(hay),
  };
}

export async function resolveFunnel() {
  const local = getLocalFunnel();
  let resolved = local;
  // ?rc=<base64 JSON> — debug/preview an override without touching Firebase
  // (same shapes accepted: flat, nested, app-convention). MKT can QA a config
  // before publishing it to Remote Config.
  const rcParam = new URLSearchParams(location.search).get('rc');
  if (rcParam) {
    try {
      const raw = JSON.parse(decodeURIComponent(escape(atob(rcParam))));
      resolved = mergeFunnel(local, raw);
    } catch (e) {
      console.warn('[funnel] bad ?rc= override:', e?.message);
    }
  } else {
    const override = await getRemoteFunnelOverride(local.funnelId || local.id);
    resolved = mergeFunnel(local, override);
  }
  const localPayment = await getLocalPaymentOverride(resolved.funnelId || resolved.id);
  if (localPayment) resolved.payment = deepMerge(resolved.payment, localPayment);
  const modes = urlModes();
  resolved.testMode = modes.test;
  if (modes.test && resolved.payment?.monkey) {
    const mk = resolved.payment.monkey;
    const slug = mk.funnelSlug || resolved.funnelId || resolved.id;
    resolved.payment = deepMerge(resolved.payment, {
      monkey: { funnelSlug: mk.funnelSlugTest || `${slug}-test` },
    });
  }
  return resolved;
}
