// Showcase — componentized + Firebase-configurable (operator 2026-06-12).
// Components: Logo + Rewards (separate logoImage/awardImage or merged
// eyebrowImage), Title, Content (video/image), Button (btnText|cta, btnColor,
// btnTextColor, btnAnimation: 'pulse'|'none').
//
// Fallback rule: a component that is empty or fails to load is either HIDDEN
// (logo/award/title:null) or replaced by a DEFAULT (title text below, content
// → a CMS style image, button → white "Continue"). Never render a broken box.

const DEFAULTS = {
  title: '❤️ Recreate the moments you thought were gone forever',
  media: 'assets/testimonials/fb-00.webp', // default content khi config trống
  cta: 'Continue',
};

export function showcase(screen, advance) {
  const root = document.createElement('section');
  root.className = 'flex h-full min-h-0 flex-1 flex-col gap-3 py-1';

  // title: undefined → default copy; explicit null/'' → hidden
  const title = screen.title === undefined ? DEFAULTS.title : screen.title;
  root.innerHTML = `
    ${logoAwardRow(screen)}
    ${title ? `
    <header class="flex shrink-0 flex-col gap-1.5 text-center">
      <h1 class="t-title t-display font-bold"${screen.titleColor ? ` style="color:${escapeAttr(screen.titleColor)}"` : ''}>${escapeHtml(title)}</h1>
      ${(screen.body || screen.subtitle) ? `<p class="t-muted t-body"${screen.subtitleColor ? ` style="color:${escapeAttr(screen.subtitleColor)}"` : ''}>${escapeHtml(screen.body || screen.subtitle)}</p>` : ''}
    </header>` : ''}
    <div class="card-surface min-h-0 flex-1 overflow-hidden rounded-2xl">
      ${mediaBlock(screen)}
    </div>
    <div class="shrink-0 pt-1">
      <button type="button" class="btn-primary" data-cta
        ${screen.btnAnimation === 'none' ? '' : 'data-cta-pulse'}
        ${btnStyle(screen)}>${escapeHtml(screen.btnText || screen.cta || DEFAULTS.cta)}</button>
    </div>
  `;

  // broken remote media → swap to CMS default instead of an empty frame
  root.querySelectorAll('img[data-media], video[data-media]').forEach((el) => {
    el.onerror = () => {
      const fallback = document.createElement('img');
      fallback.src = DEFAULTS.media;
      fallback.alt = '';
      fallback.dataset.media = '';
      fallback.className = 'h-full w-full rounded-2xl object-cover shadow-lg';
      el.replaceWith(fallback);
    };
  });
  root.querySelectorAll('img[data-optional]').forEach((el) => {
    el.onerror = () => el.remove(); // logo/award fail → hide
  });

  root.querySelector('[data-cta]').onclick = () => advance({});
  return root;
}

function logoAwardRow(screen) {
  // merged single asset (logo + award baked together)
  if (screen.eyebrowImage) {
    return `<img src="${escapeAttr(screen.eyebrowImage)}" alt="" data-optional
                 class="eyebrow-img mx-auto w-auto shrink-0 object-contain" />`;
  }
  const parts = [];
  if (screen.logoImage) {
    parts.push(`<img src="${escapeAttr(screen.logoImage)}" alt="Logo" data-optional class="eyebrow-img w-auto object-contain" />`);
  }
  if (screen.awardImage) {
    parts.push(`<img src="${escapeAttr(screen.awardImage)}" alt="Award" data-optional class="eyebrow-img w-auto object-contain" />`);
  }
  if (!parts.length) return ''; // both empty → hidden
  return `<div class="flex shrink-0 items-center justify-center gap-3">${parts.join('')}</div>`;
}

function mediaBlock(screen) {
  if (screen.video) {
    return `
      <video src="${escapeAttr(screen.video)}"
             ${screen.poster ? `poster="${escapeAttr(screen.poster)}"` : ''}
             autoplay muted loop playsinline data-media
             class="h-full w-full rounded-2xl object-cover shadow-lg">
      </video>
    `;
  }
  const src = screen.image || DEFAULTS.media;
  const fit = screen.imageAspect === 'natural' ? 'object-contain' : 'object-cover';
  return `
    <img src="${escapeAttr(src)}" alt="" data-media
         class="h-full w-full rounded-2xl ${fit} shadow-lg" />
  `;
}

function btnStyle(screen) {
  const s = [];
  if (screen.btnColor) s.push(`background:${escapeAttr(screen.btnColor)}`);
  if (screen.btnTextColor) s.push(`color:${escapeAttr(screen.btnTextColor)}`);
  return s.length ? `style="${s.join(';')}"` : '';
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
}

function escapeAttr(s) {
  return String(s).replace(/["']/g, (c) => ({ '"': '&quot;', "'": '&#39;' })[c]);
}
