// Firebase Analytics init + event tracking + Remote Config funnel overrides.
//
// To enable, fill in the config from the Firebase console
// (Project Settings → Your apps → SDK setup and configuration → Config).
// When `apiKey` is empty, events log to console only and funnel configs come
// purely from the local JSON — fine for local dev.
//
// Event names match `funnel-tracking` rule store so the downstream skill can
// classify these without a mapping translation.

import { initializeApp } from 'firebase/app';
import { getAnalytics, isSupported, logEvent } from 'firebase/analytics';
import { getRemoteConfig, fetchAndActivate, getValue } from 'firebase/remote-config';

// Fill inline, or set VITE_FIREBASE_* in .env/.env.local at build time
// (deploy tools can bake them the same way as VITE_DEFAULT_FUNNEL).
const env = import.meta.env;
const firebaseConfig = {
  apiKey: env.VITE_FIREBASE_API_KEY || '',
  authDomain: env.VITE_FIREBASE_AUTH_DOMAIN || '',
  projectId: env.VITE_FIREBASE_PROJECT_ID || '',
  storageBucket: env.VITE_FIREBASE_STORAGE_BUCKET || '',
  messagingSenderId: env.VITE_FIREBASE_MESSAGING_SENDER_ID || '',
  appId: env.VITE_FIREBASE_APP_ID || '',
  measurementId: env.VITE_FIREBASE_MEASUREMENT_ID || '',
};

let analytics = null;
let firebaseApp = null;

// Remote funnel overrides — Remote Config param `funnel_<id>` holds a JSON
// object merged over the local funnel config (top-level fields + screens
// matched by id). Lets ops tune showcase components per funnel WITHOUT a
// deploy: logoImage, awardImage (or merged eyebrowImage), title, media,
// btnText/cta, btnColor, btnTextColor, btnAnimation.
// No apiKey configured → returns null and the local JSON is used as-is.
export async function getRemoteFunnelOverride(funnelId) {
  if (!firebaseConfig.apiKey) return null;
  try {
    if (!firebaseApp) firebaseApp = initializeApp(firebaseConfig);
    const rc = getRemoteConfig(firebaseApp);
    rc.settings.minimumFetchIntervalMillis = 60_000;
    await fetchAndActivate(rc);
    const raw = getValue(rc, `funnel_${funnelId}`).asString();
    return raw ? JSON.parse(raw) : null;
  } catch (err) {
    console.warn('[firebase] remote funnel config failed:', err?.message);
    return null;
  }
}

(async () => {
  if (!firebaseConfig.apiKey) {
    console.info('[firebase] no apiKey (set VITE_FIREBASE_*) — Firebase lane off; events still go to the collector/gateway when configured.');
    return;
  }
  try {
    const supported = await isSupported();
    if (!supported) {
      console.warn('[firebase] Analytics not supported in this environment.');
      return;
    }
    if (!firebaseApp) firebaseApp = initializeApp(firebaseConfig);
    analytics = getAnalytics(firebaseApp);
    console.info('[firebase] Analytics initialized.');
  } catch (err) {
    console.warn('[firebase] init failed:', err?.message);
  }
})();

// Raw Firebase sink — event naming/params live in src/tracking.js (mirror of
// the funnel-tracking rule store). No-op when Analytics isn't configured.
export function logRaw(name, params) {
  try {
    if (analytics) {
      logEvent(analytics, name, params);
    }
  } catch (err) {
    // never let analytics errors break the funnel
    console.warn('[firebase] logEvent failed:', err?.message);
  }
}
