// Event tracking — mirrors the funnel-tracking rule store
// (po/hiepnv/artimind/web2app/skills/funnel-tracking/rules/funnel-events.yaml)
// so downstream classification needs no mapping translation.
//
// DYNAMIC BY DESIGN (operator 2026-07-03): event names derive from the screen
// TYPE, params derive from the screen's position in the resolved config
// (screen_id / screen_index / total_screens). Add or remove a screen in any
// funnel JSON and tracking keeps working — nothing here is per-screen.
// A screen type with no rule falls back to funnel_<type>_view /
// funnel_<type>_continue — same stub rule the funnel-tracking skill applies.
//
// DIMENSIONS (whiteboard 2026-07-03): every event carries the full hierarchy
//   concept_id (template.concept) → style_id → funnel_id, plus mkter (owner)
// so the report can pivot Concept / Style / Funnel and filter by MKTer.
//
// PHASE-1 QUALITY SIGNALS: continue events carry dwell_ms (time on screen)
// and the screen's key-action payload (choice / photos / skipped / value /
// discount) — screen quality = drop% + dwell + key-action skip rate.
//
// Sinks (all best-effort, never break the funnel):
//   1. Firebase Analytics (when configured) — via firebase.js logRaw
//   2. console.log [track] — debugging
//   3. First-party collector — sendBeacon NDJSON to tracking.collectUrl
//      (dev default /__track → vite middleware appends data/events/*.ndjson).
//   4. Events Gateway (funnel-monkey) — PROD lane. Contract (funnel-integration
//      docs, tracking-reference.md): POST {collectUrl}?k={project pk_} with a
//      JSON body {eventName, eventId, sourceUrl, params, user:{fbp,fbc}};
//      money keys stripped. Enabled when a pk_ is available: explicit
//      funnel.tracking = {collectUrl, pk} wins, else falls back to the baked
//      payment.monkey.publishableKey (same project key as x-publishable-key)
//      + the prod gateway host.

import { logRaw } from './firebase.js';
import { initVendors, vendorHook } from './vendors.js';

// funnel-events.yaml mirror: screen type → { view, cont } event names.
const RULES = {
  'paywall': { view: 'iap_view', cont: 'iap_btn_click' },
  'engagement-question': { view: 'funnel_question_view', cont: 'funnel_question_continue' },
  'engagement-insert': { view: 'funnel_insert_view', cont: 'funnel_insert_continue' },
  'showcase': { view: 'funnel_showcase_view', cont: 'funnel_showcase_continue' },
  'loading': { view: 'funnel_loading_view', cont: 'funnel_loading_done' },
};

const ctx = {
  funnel_id: null,
  concept_id: null,
  style_id: null,
  mkter: null,
  session_id: null,
  total_screens: 0,
  convertNumber: 0, // canon writer: lần thứ mấy user THẤY paywall (tích luỹ session)
  onPaywall: null,  // screen hiện tại nếu là paywall (để bắn iap_exit khi rời trang)
  purchased: false,
};
let collectUrl = '/__track';
// Events Gateway prod host (funnel-integration docs, hosts.md). Only used when
// a project pk_ is available — the gateway silently drops keyless beacons.
const GATEWAY_COLLECT = 'https://api-funnelmonkey-events-gateway.aperogroup.ai/api/v1/collect';
let collectPk = null;
let screenEnteredAt = 0;

function slug(type) {
  return String(type || 'unknown').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
}

function ruleFor(type) {
  if (RULES[type]) return RULES[type];
  const s = slug(type); // stub rule: funnel_<type>_view / _continue
  return { view: `funnel_${s}_view`, cont: `funnel_${s}_continue` };
}

export function initTracking(funnel, state) {
  ctx.funnel_id = funnel.funnelId || funnel.id;
  ctx.concept_id = funnel.conceptId || funnel.templateId || null;
  ctx.style_id = funnel.styleId || funnel.style || null;
  ctx.mkter = funnel.owner || null;
  ctx.session_id = state.sessionId;
  ctx.total_screens = funnel.screens?.length ?? 0;
  if (funnel.tracking?.collectUrl) collectUrl = funnel.tracking.collectUrl;
  if (funnel.tracking?.pk) collectPk = funnel.tracking.pk;
  // On a CDN/prod build a relative collector (/__track) hits the CDN, not a
  // collector — switch to the Events Gateway when the funnel carries a project
  // pk_ (explicit tracking.pk, else the baked payment.monkey key); otherwise
  // disable the beacon.
  if (import.meta.env.PROD && collectUrl && !/^https?:\/\//.test(collectUrl)) {
    const pk = collectPk || funnel.payment?.monkey?.publishableKey || null;
    if (pk) {
      collectUrl = GATEWAY_COLLECT;
      collectPk = pk;
    } else {
      collectUrl = null;
    }
  }
  // Editor / editor-preview sessions must not pollute real funnel data:
  // console only — no beacon, no Firebase.
  const q = new URLSearchParams(location.search);
  if (q.get('editor') === '1' || q.get('edpreview') === '1') {
    collectUrl = null;
    ctx.muted = true;
  }
  ctx.env = funnel.testMode ? 'test' : 'production';
  // test env: pixel TẮT (không bẩn data ads), event vẫn ghi kèm env=test
  initVendors(funnel, { muted: !!ctx.muted || funnel.testMode });
  track('funnel_start', { screens: ctx.total_screens });
  // iap_exit (canon): user đóng/thoát paywall. Web funnel không có nút X —
  // exit = rời trang / ẩn tab khi đang đứng ở paywall và chưa mua.
  const fireExit = () => {
    if (!ctx.onPaywall || ctx.purchased) return;
    track('iap_exit', {
      screen_id: ctx.onPaywall.id,
      screen_index: ctx.onPaywall.index,
      screen_type: 'paywall',
      ...iapParams(ctx.onPaywall),
    });
    ctx.onPaywall = null; // bắn 1 lần
  };
  addEventListener('pagehide', fireExit);
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') fireExit();
  });
}

// Effective type cho tracking/pixel: màn IMPORT (clone) render là 'raw' nhưng
// mang `role` (paywall/engagement-insert/…) do classifier gán → event & pixel
// bắn đúng (email→CompleteRegistration, paywall→iap_*). Màn thường: dùng type.
function etype(screen) { return screen.role || screen.type; }

function screenParams(screen) {
  return {
    screen_id: screen.id,
    screen_index: screen.index,
    screen_type: etype(screen),
  };
}

// iap_* events carry the writer-skill param set (source/entitlement/offering
// + convert_number — paywall-event-reference.md).
function iapParams(screen) {
  return {
    convert_number: ctx.convertNumber,
    source: `iap_funnel_${ctx.funnel_id}_screen_${screen?.index ?? 'return'}`,
    entitlement_id: 'Artimind Pro',
    offering_id: 'default',
  };
}
export function iapGlobalParams() {
  return { convert_number: ctx.convertNumber, entitlement_id: 'Artimind Pro', offering_id: 'default' };
}

export function trackScreenView(screen) {
  screenEnteredAt = Date.now();
  const t = etype(screen);
  ctx.onPaywall = t === 'paywall' ? screen : null;
  if (t === 'paywall') ctx.convertNumber += 1;
  const extra = t === 'paywall' ? iapParams(screen) : {};
  track(ruleFor(t).view, { ...screenParams(screen), ...extra });
}

export function trackScreenContinue(screen, payload = {}) {
  const t = etype(screen);
  const p = {
    ...screenParams(screen),
    dwell_ms: screenEnteredAt ? Date.now() - screenEnteredAt : null,
    ...payload,
  };
  if (t === 'engagement-question' && payload.choice !== undefined) {
    p.selected_value = payload.choice;
    delete p.choice;
  }
  if (t === 'paywall') {
    Object.assign(p, iapParams(screen));
    if (payload.plan) { p.package_id = payload.plan; delete p.plan; }
  }
  track(ruleFor(t).cont, p);
  if (t === 'paywall') ctx.onPaywall = null;
}

export function trackPaywallExit(screen) {
  track('iap_exit', { ...screenParams(screen), ...iapParams(screen) });
}

export function markPurchased() {
  ctx.purchased = true;
  ctx.onPaywall = null;
}

export function trackFunnelComplete(state) {
  track('funnel_complete', {
    duration_ms: Date.now() - state.startedAt,
    answers_count: Object.keys(state.answers).length,
    discount_pct: state.discountPct ?? 0,
  });
}

// Semantic extras — follow the funnel_* / iap_* families:
//   funnel_wheel_spin {discount_pct} · funnel_plan_select {package_id}
//   iap_checkout_open {provider, package_id} · iap_successfull {provider,
//   purchase_package_id, convert_number} · confirm_purchased_fail {package_id, msg, code}
export function track(name, params = {}) {
  const ev = {
    event: name,
    ts: new Date().toISOString(),
    funnel_id: ctx.funnel_id,
    concept_id: ctx.concept_id,
    style_id: ctx.style_id,
    mkter: ctx.mkter,
    session_id: ctx.session_id,
    total_screens: ctx.total_screens,
    env: ctx.env || 'production',
    ...params,
  };
  console.log(`[track] ${name}`, ev);
  if (ctx.muted) return; // editor/preview session — console only
  logRaw(name, ev);
  vendorHook(name, ev); // FB Pixel mapping (PageView/ViewContent/Lead/InitiateCheckout/Purchase)
  beacon(ev);
}

function cookie(name) {
  const m = document.cookie.match(new RegExp(`(?:^|; )${name}=([^;]+)`));
  return m ? decodeURIComponent(m[1]) : undefined;
}

function beacon(ev) {
  if (!collectUrl) return;
  try {
    if (collectPk) {
      // Events Gateway contract: JSON body, pk_ via ?k= (sendBeacon can't set
      // headers), Content-Type application/json REQUIRED, money keys stripped
      // (the Stripe-webhook Purchase carries the authoritative value).
      const { event, ts, ...params } = ev;
      for (const k of ['value', 'currency', 'revenue']) delete params[k];
      const payload = JSON.stringify({
        eventName: event,
        eventId: crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`,
        sourceUrl: location.href,
        params,
        user: { fbp: cookie('_fbp'), fbc: cookie('_fbc') },
      });
      const url = `${collectUrl}?k=${encodeURIComponent(collectPk)}`;
      const ok = navigator.sendBeacon?.(url, new Blob([payload], { type: 'application/json' }));
      if (!ok) {
        fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: payload, keepalive: true }).catch(() => {});
      }
      return;
    }
    const line = JSON.stringify(ev) + '\n';
    const ok = navigator.sendBeacon?.(collectUrl, new Blob([line], { type: 'application/x-ndjson' }));
    if (!ok) {
      fetch(collectUrl, { method: 'POST', body: line, keepalive: true }).catch(() => {});
    }
  } catch {
    /* tracking must never break the funnel */
  }
}
