// Trust / social-proof stats screen (reunion screen 08 original structure):
// live count-up number, "Families reunited..." as TEXT (was an image on live —
// operator 2026-06-12), then "Trusted by leading media" text logos.

import gsap from 'gsap';

export function trust(screen, advance) {
  const root = document.createElement('section');
  root.className = 'flex h-full min-h-0 flex-1 flex-col gap-4 py-2';
  const target = screen.counter ?? 1486211;

  root.innerHTML = `
    ${
      screen.eyebrowImage
        ? `<img src="${escapeAttr(screen.eyebrowImage)}" alt="" class="eyebrow-img mx-auto w-auto shrink-0 object-contain" />`
        : ''
    }
    <div class="flex min-h-0 flex-1 flex-col items-center justify-center gap-3 overflow-y-auto text-center">
      <div class="trust-counter" data-counter>0</div>
      <p class="t-title t-body max-w-[300px] font-semibold leading-snug">
        ${escapeHtml(screen.counterLabel || 'Families reunited with their loved ones through Artimind ✨')}
      </p>
      <div class="mx-auto my-1 h-px w-3/4" style="background: var(--c-border)"></div>
      ${Array.isArray(screen.logos) && screen.logos.length ? `
      <p class="t-muted t-body">${escapeHtml(screen.mediaTitle || 'Trusted by leading media:')}</p>
      <div class="flex flex-col items-center gap-3 pt-1" data-stagger>
        ${mediaLogos(screen)}
      </div>` : ''}
    </div>
    <div class="shrink-0 pt-1">
      <button type="button" class="btn-primary" data-cta data-cta-pulse>${escapeHtml(screen.cta || 'Continue')}</button>
    </div>
  `;

  const counterEl = root.querySelector('[data-counter]');
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) {
    counterEl.textContent = target.toLocaleString('en-US');
  } else {
    const obj = { val: target * 0.86 }; // start near the target so it reads "live"
    counterEl.textContent = Math.floor(obj.val).toLocaleString('en-US');
    gsap.to(obj, {
      val: target,
      duration: 2.4,
      ease: 'power2.out',
      onUpdate: () => { counterEl.textContent = Math.floor(obj.val).toLocaleString('en-US'); },
      onComplete: () => {
        // keep the stat feeling alive: +1 family every few seconds
        let n = target;
        setInterval(() => {
          if (!counterEl.isConnected) return;
          n += 1;
          counterEl.textContent = n.toLocaleString('en-US');
        }, 3500);
      },
    });
  }

  root.querySelector('[data-cta]').onclick = () => advance({});
  return root;
}

// Logos = ẢNH (operator 2026-07-03 — không dùng text). screen.logos là mảng
// URL ảnh (upload từ kho creative); entry không phải URL vẫn render text để
// không vỡ config cũ, nhưng setup chuẩn là ảnh. Rỗng → ẩn khu logos.
function mediaLogos(screen) {
  const items = Array.isArray(screen.logos) ? screen.logos : [];
  return items
    .map((l) =>
      /^(https?:\/\/|uploads\/|assets\/)/.test(l)
        ? `<img src="${escapeAttr(l)}" alt="" class="media-logo h-8 w-auto object-contain" />`
        : `<span class="media-logo text-xl font-bold">${escapeHtml(l)}</span>`,
    )
    .join('');
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
}

function escapeAttr(s) {
  return String(s).replace(/["']/g, (c) => ({ '"': '&quot;', "'": '&#39;' })[c]);
}
