// Paddle adapter — Paddle.js v2 overlay checkout.
//
// Config (funnel.payment.paddle): { env: 'sandbox'|'live', clientToken,
//   priceIds: { week, month, year } } — clientToken is Paddle's CLIENT-SIDE
// token (Developer Tools → Authentication → Client-side tokens); priceIds are
// pri_… catalog prices. No account yet → leave empty; the card/mock path
// keeps the funnel demoable.
//
// customData.session_id carries the funnel session for revenue attribution.

import { closeModal } from './modal.js';

let sdkPromise = null;
function loadSdk() {
  if (window.Paddle) return Promise.resolve();
  if (sdkPromise) return sdkPromise;
  sdkPromise = new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = 'https://cdn.paddle.com/paddle/v2/paddle.js';
    s.onload = resolve;
    s.onerror = () => reject(new Error('Paddle.js failed to load'));
    document.head.appendChild(s);
  });
  return sdkPromise;
}

let initialized = false;

export async function checkout(cfg, plan, { done, fail, sessionId }) {
  const priceId = cfg?.priceIds?.[plan?.id];
  if (!cfg?.clientToken) { fail?.(new Error('Paddle not configured')); return { ok: false }; }
  if (!priceId) { fail?.(new Error(`No Paddle price id for "${plan?.id}"`)); return { ok: false }; }
  try {
    await loadSdk();
    if (!initialized) {
      if ((cfg.env || 'sandbox') === 'sandbox') window.Paddle.Environment.set('sandbox');
      window.Paddle.Initialize({
        token: cfg.clientToken,
        eventCallback: (ev) => {
          if (ev?.name === 'checkout.completed') {
            closeModal();
            done?.({ transaction_id: ev.data?.transaction_id });
          }
          if (ev?.name === 'checkout.error') fail?.(new Error(ev.detail || 'Paddle checkout error'));
        },
      });
      initialized = true;
    }
    // Paddle renders its own overlay — no shared modal needed.
    window.Paddle.Checkout.open({
      items: [{ priceId, quantity: 1 }],
      customData: { session_id: sessionId || '' },
    });
    return { ok: true, provider: 'paddle' };
  } catch (e) {
    fail?.(e);
    return { ok: false, error: e };
  }
}
