import { setAnswer, setEmail } from '../state.js';

// Input screen — form fills the column; submit button anchors to the bottom
// via mt-auto so it is always on-screen.
// `optional: true` → never blocks: CTA always enabled, empty submit advances
// with value "". UX writing: mark optionality IN the placeholder, helper text
// below the input (operator 2026-06-12).

export function engagementInsert(screen, advance) {
  const root = document.createElement('section');
  root.className = 'flex h-full min-h-0 flex-1 flex-col gap-5 py-2';
  const type = screen.inputType || 'text';
  const optional = Boolean(screen.optional);
  const placeholder = screen.placeholder || (optional ? 'Your answer (optional)' : '');
  const cta = screen.cta || 'Continue';
  root.innerHTML = `
    ${
      screen.eyebrowImage
        ? `<img src="${escapeAttr(screen.eyebrowImage)}" alt="" class="eyebrow-img mx-auto w-auto shrink-0 object-contain" />`
        : ''
    }
    <header class="flex shrink-0 flex-col gap-2 text-center">
      <h1 class="t-title t-screen-title font-bold">
        ${escapeHtml(screen.question || 'Enter your details')}
      </h1>
      ${screen.subtitle ? `<p class="t-muted t-body">${escapeHtml(screen.subtitle)}</p>` : ''}
    </header>
    <form class="flex min-h-0 flex-1 flex-col gap-3" data-form novalidate>
      <input
        type="${type}"
        ${optional ? '' : 'required'}
        class="input-field"
        placeholder="${escapeAttr(placeholder)}"
        autocomplete="${suggestAutocomplete(type, screen.name)}"
      />
      ${screen.helper ? `<p class="t-muted t-body">${escapeHtml(screen.helper)}</p>` : ''}
      <p class="hidden text-sm" style="color:var(--c-danger)" data-error></p>
      <div class="mt-auto flex shrink-0 flex-col gap-2 pb-1">
        ${screen.note ? `<p class="t-faint t-small text-center">${escapeHtml(screen.note)}</p>` : ''}
        <button type="submit" class="btn-primary">${escapeHtml(cta)}</button>
      </div>
    </form>
  `;
  const form = root.querySelector('[data-form]');
  const errorEl = root.querySelector('[data-error]');
  // soft, human error copy (operator 2026-06-12: "viết mềm mại hơn"). These are
  // DEFAULTS — overridable from Firebase per screen via `emptyError` /
  // `invalidError` (flat keys `scrN_error_empty` / `scrN_error_invalid`),
  // operator 2026-06-15.
  const emptyMsg =
    screen.emptyError ||
    (type === 'email'
      ? "We'd love to send your video to you — please add your email 💌"
      : 'Almost there — could you fill this in for us?');
  const invalidMsg =
    screen.invalidError ||
    (type === 'email'
      ? 'Hmm, that email looks a little off — mind double-checking it?'
      : 'That doesn’t look quite right — mind checking it again?');
  form.onsubmit = (e) => {
    e.preventDefault();
    const input = form.querySelector('input');
    const value = input.value.trim();
    if (!optional) {
      if (!value) {
        errorEl.textContent = emptyMsg;
        errorEl.classList.remove('hidden');
        input.focus();
        return;
      }
      if (!input.checkValidity()) {
        errorEl.textContent = invalidMsg;
        errorEl.classList.remove('hidden');
        input.focus();
        return;
      }
    }
    errorEl.classList.add('hidden');
    setAnswer(screen.id, value);
    if (type === 'email' && value) setEmail(value); // buyer email — lần nhập cuối thắng
    advance({ value, skipped: optional && !value });
  };
  return root;
}

function suggestAutocomplete(type, name) {
  if (type === 'email') return 'email';
  if (type === 'tel') return 'tel';
  if (name === 'age') return 'bday';
  return 'off';
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
}

function escapeAttr(s) {
  return String(s).replace(/["']/g, (c) => ({ '"': '&quot;', "'": '&#39;' })[c]);
}
