// Đẩy ảnh khách lên S3 qua presigned URL (operator 2026-10-14).
//   1. POST {presignUrl} {fileName, contentType, contentMD5} → server funnel ký,
//      xin BE-Artimind → {presignedUrl, objectKey, url}
//   2. PUT presignedUrl, bytes trần, Content-Type + Content-MD5 khớp bước 1.
// Key ký chỉ nằm ở server (server/funnel_upload.mjs), không bao giờ ở đây.
import SparkMD5 from 'spark-md5';

const DEFAULT_PRESIGN = import.meta.env.VITE_UPLOAD_PRESIGN_URL || '/__upload/presign';

async function md5Base64(blob) {
  const hex = SparkMD5.ArrayBuffer.hash(await blob.arrayBuffer(), true); // raw binary string
  return btoa(hex);
}

export async function uploadPhoto(file, { presignUrl = DEFAULT_PRESIGN } = {}) {
  const contentType = file.type || 'image/jpeg';
  const contentMD5 = await md5Base64(file);
  const ext = (file.name.match(/\.([A-Za-z0-9]+)$/) || [])[1] || contentType.split('/')[1] || 'jpg';
  const pre = await fetch(presignUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ fileName: `photo.${ext}`, contentType, contentMD5 }),
  });
  const body = await pre.json().catch(() => ({}));
  if (!pre.ok) throw new Error(`presign ${pre.status}: ${body.error || ''}`);
  const put = await fetch(body.presignedUrl, {
    method: 'PUT',
    headers: { 'Content-Type': contentType, 'Content-MD5': contentMD5 },
    body: file,
  });
  if (!put.ok) throw new Error(`S3 PUT ${put.status}`);
  return { url: body.url, objectKey: body.objectKey };
}
