// In-memory state — single-page lifetime. Quiz answers + session metadata persist
// across screens but are lost on page reload (intentional: refresh = new funnel run).

const state = {
  sessionId: crypto.randomUUID(),
  startedAt: Date.now(),
  answers: {},        // screen.id → user choice / value
  currentIndex: 0,
  discountPct: null,  // set by the wheel screen; paywall reflects it in pricing
  email: null,        // buyer email — màn nhập email SAU CÙNG thắng (operator 2026-07-03)
};

export function getState() {
  return state;
}

export function setAnswer(screenId, value) {
  state.answers[screenId] = value;
}

export function setIndex(i) {
  state.currentIndex = i;
}

export function setDiscount(pct) {
  state.discountPct = pct;
}

export function setEmail(v) {
  state.email = v;
}
