// Post-purchase success — theo ĐÚNG màn "Success_download" của funnelfox
// (config 01KTP33XHY…, screen kUab49Xi — operator 2026-07-03):
//   "Just one more step!" + 4 bước (nhớ email {{email}} → bấm Download →
//   mở app "Have an account? Sign in" → nhập đúng email) + nút Download.
// {{email}} = buyer email user đã nhập trong funnel (state.email).
// Đây là màn CUỐI — CTA mở App Store (same-tab → iOS mở sheet store từ dưới
// lên), KHÔNG advance tiếp (không bao giờ rơi vào màn debug).
// Config: { title?, body?, steps?[], cta?, ctaUrl?, note? }

import { getState } from '../state.js';
import { track } from '../tracking.js';

const DEFAULT_STEPS = [
  'Remember the email you used {{email}}',
  'Click the button below to download the app',
  'Open the app and tap "Have an account? Sign in"',
  'Enter the email that you used for signing up {{email}}',
];

export function successfull(screen, advance) { // eslint-disable-line no-unused-vars
  const root = document.createElement('section');
  root.className = 'relative flex h-full min-h-0 flex-1 flex-col py-2';
  const state = getState();
  const email = state.email || '';
  const emailChip = email
    ? `<span class="rounded-md px-1.5 py-0.5 font-semibold" style="background:rgba(255,199,59,.18);color:var(--c-gold)">${escapeHtml(email)}</span>`
    : '';
  const steps = (screen.steps?.length ? screen.steps : DEFAULT_STEPS)
    .map((t) => escapeHtml(String(t)).replace('{{email}}', emailChip || 'your email'));

  root.innerHTML = `
    <div class="screen-scroll flex flex-col gap-5" style="padding-bottom:116px">
      <header class="flex flex-col items-center gap-2 pt-6 text-center">
        <div class="text-5xl">🎉</div>
        <h1 class="t-title t-screen-title font-bold">${escapeHtml(screen.title || 'Just one more step!')}</h1>
        ${screen.body ? `<p class="t-muted t-body">${escapeHtml(screen.body)}</p>` : ''}
      </header>
      <ol class="flex flex-col gap-3" data-stagger>
        ${steps.map((t, i) => `
          <li class="card-surface flex items-start gap-3 rounded-2xl p-3.5">
            <span class="flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-sm font-bold"
                  style="background:var(--c-gold);color:#42050A">${i + 1}</span>
            <span class="t-title t-body pt-0.5">${t}</span>
          </li>`).join('')}
      </ol>
      ${screen.note ? `<p class="t-faint text-center text-xs">${escapeHtml(screen.note)}</p>` : ''}
    </div>
    <div class="cta-dock">
      <button type="button" class="btn-primary" data-cta data-cta-pulse>${escapeHtml(screen.cta || 'Download')}</button>
      <p class="t-faint pt-2 text-center text-xs">⭐️ 4.7 Average rating on App Store</p>
    </div>
  `;
  root.querySelector('[data-cta]').onclick = () => {
    track('funnel_successfull_continue', {
      screen_id: screen.id, screen_index: screen.index, screen_type: 'successfull', via: 'download_app',
    });
    // App Store universal link — same-tab để iOS mở sheet store từ dưới lên
    if (screen.ctaUrl) location.href = screen.ctaUrl;
  };
  return root;
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
}
