// Payments orchestrator — provider-adapter layer for the paywall.
//
// Providers (config-driven per funnel via funnel.payment, deep-merged from
// template → clone overrides → public/payment.local.json):
//   card   → funnel-monkey (Apero's FunnelFox-clone) — dynamic offer + Stripe
//            EMBEDDED checkout (monkey.js). Falls back to the mock card form
//            when monkey isn't configured (POC demo keeps working).
//   paypal → PayPal JS SDK subscription buttons (paypal.js)
//   paddle → Paddle.js v2 overlay checkout (paddle.js)
//
// Every checkout path emits the iap_* event family (tracking.js):
//   iap_checkout_open {provider, package_id}
//   iap_successfull   {provider, purchase_package_id, discount_pct}
//   confirm_purchased_fail {package_id, msg, code} (canon writer)

import { track, iapGlobalParams, markPurchased } from '../tracking.js';
import { getState } from '../state.js';
import { openModal, closeModal, modalBody } from './modal.js';
import * as monkey from './monkey.js';
import * as paypal from './paypal.js';
import * as paddle from './paddle.js';

export function paymentConfig(funnel) {
  return funnel?.payment || {};
}

export function availableProviders(funnel) {
  const cfg = paymentConfig(funnel);
  const list = [];
  // card is always available: monkey when configured, else mock (demo)
  list.push({ id: 'card', label: 'Card', live: monkey.isConfigured(cfg.monkey) });
  if (cfg.paypal?.clientId) list.push({ id: 'paypal', label: 'PayPal', live: true });
  if (cfg.paddle?.clientToken) list.push({ id: 'paddle', label: 'Paddle', live: true });
  const wanted = Array.isArray(cfg.providers) ? cfg.providers : null;
  return wanted ? list.filter((p) => wanted.includes(p.id)) : list;
}

// Dynamic plans: funnel-monkey offer (when configured) → paywall plan shape;
// null → paywall keeps its local config plans.
export async function loadRemotePlans(funnel) {
  const cfg = paymentConfig(funnel);
  if (!monkey.isConfigured(cfg.monkey)) return null;
  return monkey.getOfferPlans(cfg.monkey);
}

// Inline Stripe (funnel-monkey) — paywall nhúng thẳng form embedded dưới
// list gói khi monkey đã config. Trả handle {destroy} hoặc null khi chưa config.
export function hasInlineStripe(funnel) {
  return monkey.isConfigured(paymentConfig(funnel).monkey);
}
export async function mountInlineCheckout(funnel, plan, mountEl, { screen } = {}) {
  const cfg = paymentConfig(funnel);
  const state = getState();
  track('iap_checkout_open', {
    provider: 'card', via: 'inline_embed',
    package_id: plan?.id,
    discount_pct: state.discountPct ?? 0,
    screen_id: screen?.id, screen_index: screen?.index,
  });
  const amt = typeof plan?.amount === 'number' ? plan.amount : (/^\$([\d.]+)$/.exec(String(plan?.price || '')) ? parseFloat(RegExp.$1) : undefined);
  const validEmail = state.email && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(state.email) ? state.email : undefined;
  return monkey.mountInline(cfg.monkey, plan, mountEl, {
    sessionId: state.sessionId,
    customerEmail: validEmail, // chỉ gửi khi hợp lệ — funnel-monkey 400 nếu sai

    // Stripe onComplete = pay THÀNH CÔNG trong iframe → bắn iap_successfull
    // ngay (beacon keepalive, không rớt khi redirect); đặt cờ để trang
    // ?status=complete sau redirect KHÔNG bắn trùng.
    onComplete: () => {
      markPurchased();
      try { sessionStorage.setItem('fm_paid_fired', '1'); } catch { /* noop */ }
      track('iap_successfull', {
        provider: 'card', via: 'stripe_oncomplete',
        purchase_package_id: plan?.id,
        discount_pct: state.discountPct ?? 0,
        value: amt,
        currency: plan?.currency || 'USD',
        ...iapGlobalParams(),
      });
    },
  });
}

// Entry point from the paywall CTA / provider buttons.
export async function startCheckout(funnel, { provider, plan, screen }) {
  const cfg = paymentConfig(funnel);
  const state = getState();
  track('iap_checkout_open', {
    provider,
    package_id: plan?.id,
    discount_pct: state.discountPct ?? 0,
    screen_id: screen?.id,
    screen_index: screen?.index,
  });
  const done = (info) => {
    markPurchased();
    const m = /^\$([\d.]+)$/.exec(String(plan?.price || '').trim());
    track('iap_successfull', {
      provider,
      purchase_package_id: plan?.id,
      discount_pct: state.discountPct ?? 0,
      value: typeof plan?.amount === 'number' ? plan.amount : (m ? parseFloat(m[1]) : undefined),
      currency: 'USD',
      ...iapGlobalParams(),
      ...info,
    });
  };
  // canon event-tracking-writer: lỗi thanh toán = confirm_purchased_fail
  // {package_id, msg, code}
  const fail = (err) => {
    track('confirm_purchased_fail', {
      provider,
      package_id: plan?.id,
      msg: String(err?.message || err).slice(0, 100),
      code: err?.code || err?.name || 'unknown',
    });
  };

  try {
    if (provider === 'paypal') {
      return await paypal.checkout(cfg.paypal, plan, { done, fail, sessionId: state.sessionId });
    }
    if (provider === 'paddle') {
      return await paddle.checkout(cfg.paddle, plan, { done, fail, sessionId: state.sessionId });
    }
    // card
    if (monkey.isConfigured(cfg.monkey)) {
      return await monkey.checkout(cfg.monkey, plan, { done, fail, sessionId: state.sessionId, customerEmail: state.email || undefined });
    }
    return mockCheckout(plan, { done });
  } catch (e) {
    fail(e);
    throw e;
  }
}

// Mock card checkout — demo path when no provider is configured. Simulates a
// short processing delay then resolves success (never charges anything).
function mockCheckout(plan, { done }) {
  return new Promise((resolve) => {
    openModal(`Complete your purchase — ${plan?.label || 'plan'}`);
    modalBody().innerHTML = `
      <div class="flex flex-col items-center gap-3 py-8 text-center">
        <div class="text-4xl">🧪</div>
        <p class="t-title font-semibold">Mock checkout (no provider configured)</p>
        <p class="t-muted text-sm">Simulating payment…</p>
      </div>`;
    setTimeout(() => {
      closeModal();
      done({ mock: true });
      resolve({ ok: true, provider: 'mock' });
    }, 1200);
  });
}

// Stripe embedded checkout returns to the page with ?status=complete
// (&session_id=…). Called on boot: true → router shows the success screen.
export function handleCheckoutReturn(funnel, showSuccess) {
  const q = new URLSearchParams(location.search);
  if (q.get('status') !== 'complete') return false;
  markPurchased();
  let alreadyFired = false;
  try {
    alreadyFired = sessionStorage.getItem('fm_paid_fired') === '1';
    sessionStorage.removeItem('fm_paid_fired');
  } catch { /* noop */ }
  if (!alreadyFired) {
    track('iap_successfull', {
      provider: 'card',
      purchase_package_id: q.get('plan') || null,
      checkout_session: q.get('session_id') || null,
      via: 'embedded_return',
      ...iapGlobalParams(),
    });
  }
  try {
    q.delete('status'); q.delete('session_id'); q.delete('plan');
    const rest = q.toString();
    history.replaceState(null, '', location.pathname + (rest ? `?${rest}` : ''));
  } catch { /* noop */ }
  showSuccess({ provider: 'Stripe' });
  return true;
}
