// Photo-upload engagement screen — original funnel layout (operator 2026-06-12):
// title → TWO TALL portrait upload zones (the hero) → CTA dock → note → rings.
// After picking, the zone shows the preview with a "CHANGE PHOTO" overlay —
// tapping again re-opens the picker. CTA is enabled by default so the flow is
// never blocked (operator defaults rule); photo count goes in the payload.
// Mặc định ảnh KHÔNG rời browser — chỉ filename vào state. Funnel bật
// `screen.upload.enabled` (operator 2026-10-14) → chọn ảnh xong đẩy S3 ngay
// qua presigned URL (src/photo-upload.js); state lưu {name, url, objectKey}; photos_uploaded đếm theo objectKey.
// Upload lỗi/chậm KHÔNG chặn flow: CTA chờ tối đa upload.waitMs rồi đi tiếp.

import { setAnswer } from '../state.js';
import { uploadPhoto } from '../photo-upload.js';

export function engagementUpload(screen, advance) {
  const root = document.createElement('section');
  root.className = 'relative flex h-full min-h-0 flex-1 flex-col py-1';
  const zones = screen.zones?.length ? screen.zones : ['UPLOAD YOUR 1ST PHOTO', 'UPLOAD YOUR 2ND PHOTO'];
  const cta = screen.cta || 'CREATE NOW';

  root.innerHTML = `
    ${
      screen.eyebrowImage
        ? `<img src="${escapeAttr(screen.eyebrowImage)}" alt="" class="eyebrow-img mx-auto w-auto shrink-0 object-contain" />`
        : ''
    }
    <div class="screen-scroll flex flex-col gap-4">
      <header class="flex flex-col gap-2 text-center">
        <h1 class="t-title t-screen-title font-bold">${escapeHtml(screen.title || 'Upload your photos')}</h1>
        ${screen.subtitle ? `<p class="t-muted t-body">${escapeHtml(screen.subtitle)}</p>` : ''}
      </header>
      <div class="grid shrink-0 grid-cols-2 gap-3" data-zones data-stagger></div>
      ${screen.note ? `<p class="t-title t-body shrink-0 text-center font-semibold">${escapeHtml(screen.note)}</p>` : ''}
    </div>
    <div class="cta-dock">
      <button type="button" class="btn-primary" data-cta data-cta-pulse>${escapeHtml(cta)}</button>
    </div>
  `;

  const zonesBox = root.querySelector('[data-zones]');
  const ctaBtn = root.querySelector('[data-cta]');
  const picked = new Array(zones.length).fill(null);
  const up = screen.upload?.enabled ? screen.upload : null;
  const uploads = new Array(zones.length).fill(null); // Promise<{url, objectKey}|null>

  zones.forEach((label, i) => {
    const zone = document.createElement('label');
    zone.className = 'upload-zone upload-zone-tall p-3'; // tall portrait like the live funnel
    zone.innerHTML = `
      <input type="file" accept="image/*" class="hidden" data-input />
      <div class="flex flex-col items-center gap-3" data-placeholder>
        <span class="t-faint text-5xl font-light leading-none">+</span>
        <span class="t-muted t-body font-bold uppercase tracking-wide">${escapeHtml(label)}</span>
      </div>
      <img class="hidden h-full w-full rounded-xl object-cover" data-preview alt="Selected photo" />
      <span class="change-overlay">CHANGE<br/>PHOTO</span>
    `;
    const input = zone.querySelector('[data-input]');
    const placeholder = zone.querySelector('[data-placeholder]');
    const preview = zone.querySelector('[data-preview]');
    input.onchange = () => {
      const file = input.files?.[0];
      if (!file) return;
      picked[i] = file.name;
      preview.src = URL.createObjectURL(file);
      preview.classList.remove('hidden');
      placeholder.classList.add('hidden');
      zone.classList.add('filled'); // shows CHANGE PHOTO overlay; click re-picks
      if (up) {
        uploads[i] = uploadPhoto(file, { presignUrl: up.presignUrl }).catch((e) => {
          console.warn('[upload] lỗi, flow vẫn đi tiếp:', e.message);
          return null;
        });
      }
    };
    zonesBox.appendChild(zone);
  });


  ctaBtn.onclick = async () => {
    if (!up) {
      setAnswer(screen.id, picked);
      advance({ photos: picked.filter(Boolean).length });
      return;
    }
    ctaBtn.disabled = true;
    const timeout = new Promise((ok) => setTimeout(ok, up.waitMs ?? 8000, 'timeout'));
    const done = await Promise.race([Promise.all(uploads.map((p) => p || null)), timeout]);
    const results = done === 'timeout' ? [] : done;
    const photos = picked.map((name, i) => (name ? { name, url: results[i]?.url || null, objectKey: results[i]?.objectKey || null } : null));
    setAnswer(screen.id, photos);
    advance({ photos: picked.filter(Boolean).length, photos_uploaded: photos.filter((p) => p?.objectKey).length });
  };

  return root;
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c],
  );
}

function escapeAttr(s) {
  return String(s).replace(/["']/g, (c) => ({ '"': '&quot;', "'": '&#39;' })[c]);
}
